window.DRAGONSCRIPT_FILES = {
  "ast_nodes.py": "\"\"\"\nast_nodes.py\n============\nNodos del Árbol de Sintaxis Abstracta (AST) de DragonScript.\n\nCada nodo es una simple clase de datos (usamos ``dataclass``) que representa\nuna construcción del lenguaje. El Parser produce estos nodos y el Interpreter\nlos recorre (tree-walking).\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Any, Optional\n\n\nclass Node:\n    \"\"\"Clase base de todos los nodos del AST.\"\"\"\n    line: int = 0\n\n\n# --------------------------------------------------------------- estructura\n@dataclass\nclass Program(Node):\n    statements: list[Node] = field(default_factory=list)\n    line: int = 0\n\n\n@dataclass\nclass Block(Node):\n    statements: list[Node] = field(default_factory=list)\n    line: int = 0\n\n\n# --------------------------------------------------------------- literales\n@dataclass\nclass NumberLiteral(Node):\n    value: float | int\n    line: int = 0\n\n\n@dataclass\nclass StringLiteral(Node):\n    value: str\n    line: int = 0\n\n\n@dataclass\nclass BooleanLiteral(Node):\n    value: bool\n    line: int = 0\n\n\n@dataclass\nclass NullLiteral(Node):\n    line: int = 0\n\n\n@dataclass\nclass ArrayLiteral(Node):\n    elements: list[Node] = field(default_factory=list)\n    line: int = 0\n\n\n@dataclass\nclass RangeLiteral(Node):\n    \"\"\"Rango de enteros inclusivo: ``[inicio..fin]`` -> lista [inicio, ..., fin].\"\"\"\n    start: Node\n    end: Node\n    line: int = 0\n\n\n@dataclass\nclass Identifier(Node):\n    name: str\n    line: int = 0\n\n\n# ------------------------------------------------------------- expresiones\n@dataclass\nclass BinaryOp(Node):\n    left: Node\n    operator: str\n    right: Node\n    line: int = 0\n\n\n@dataclass\nclass UnaryOp(Node):\n    operator: str\n    operand: Node\n    line: int = 0\n\n\n@dataclass\nclass MemberAccess(Node):\n    obj: Node\n    member: str\n    line: int = 0\n\n\n@dataclass\nclass IndexAccess(Node):\n    obj: Node\n    index: Node\n    line: int = 0\n\n\n@dataclass\nclass TechniqueCall(Node):\n    callee: Node\n    arguments: list[Node] = field(default_factory=list)\n    line: int = 0\n\n\n# ------------------------------------------------------------- sentencias\n@dataclass\nclass KIDeclaration(Node):\n    \"\"\"Declaración de variable: ``KI nombre = valor``.\"\"\"\n    name: str\n    value: Optional[Node] = None\n    line: int = 0\n\n\n@dataclass\nclass Assignment(Node):\n    \"\"\"Asignación a una variable existente: ``nombre = valor``.\"\"\"\n    target: Node\n    value: Node\n    line: int = 0\n\n\n@dataclass\nclass CompoundAssignment(Node):\n    \"\"\"Asignación compuesta: ``nombre += valor`` (y -=, *=, /=).\"\"\"\n    target: Node\n    operator: str  # '+=', '-=', '*=', '/='\n    value: Node\n    line: int = 0\n\n\n@dataclass\nclass Scouter(Node):\n    \"\"\"Instrucción de salida: ``SCOUTER expr``.\"\"\"\n    expression: Node\n    line: int = 0\n\n\n@dataclass\nclass IfStatement(Node):\n    condition: Node\n    then_branch: Block\n    # Lista de (condición, bloque) para cada ``ELSE IF``.\n    elif_branches: list[tuple[Node, Block]] = field(default_factory=list)\n    else_branch: Optional[Block] = None\n    line: int = 0\n\n\n@dataclass\nclass WhileStatement(Node):\n    condition: Node\n    body: Block\n    line: int = 0\n\n\n@dataclass\nclass ForEachStatement(Node):\n    \"\"\"Recorrido enumerativo: ``RASTREAR x EN grupo { ... }``.\n\n    Recorre cada elemento de ``iterable`` (una lista o cadena), ligando cada\n    valor a la variable ``var_name`` dentro del cuerpo.\n    \"\"\"\n    var_name: str\n    iterable: Node\n    body: Block\n    line: int = 0\n\n\n@dataclass\nclass GravityStatement(Node):\n    \"\"\"Bucle temático: ``GRAVITY N { ... }`` ejecuta el bloque N veces.\"\"\"\n    count: Node\n    body: Block\n    line: int = 0\n\n\n@dataclass\nclass TechniqueDeclaration(Node):\n    \"\"\"Definición de función: ``TECHNIQUE nombre(params) { ... }``.\n\n    Cuando aparece dentro de una clase (``WARRIOR``) y va precedida de\n    ``STATIC``, ``is_static`` es ``True`` y el método no recibe ``SELF``.\n    \"\"\"\n    name: str\n    params: list[str] = field(default_factory=list)\n    body: Block = field(default_factory=Block)\n    is_static: bool = False\n    line: int = 0\n\n\n@dataclass\nclass WarriorDeclaration(Node):\n    \"\"\"Definición de clase: ``WARRIOR Nombre [EVOLVES Padre1, Padre2] { ... }``.\n\n    * ``methods``            — métodos de instancia y estáticos (TechniqueDeclaration).\n    * ``class_attributes``   — atributos de clase compartidos ``(nombre, valor_node)``.\n    \"\"\"\n    name: str\n    parents: list[str] = field(default_factory=list)\n    methods: list[\"TechniqueDeclaration\"] = field(default_factory=list)\n    class_attributes: list[tuple[str, \"Node\"]] = field(default_factory=list)\n    line: int = 0\n\n\n@dataclass\nclass CreateExpression(Node):\n    \"\"\"Instanciación de una clase: ``CREATE Nombre(args)``.\"\"\"\n    class_name: str\n    arguments: list[Node] = field(default_factory=list)\n    line: int = 0\n\n\n@dataclass\nclass ReturnStatement(Node):\n    value: Optional[Node] = None\n    line: int = 0\n\n\n@dataclass\nclass ExpressionStatement(Node):\n    \"\"\"Una expresión usada como sentencia (por ejemplo, una llamada).\"\"\"\n    expression: Node\n    line: int = 0\n",
  "Biblioteca.ds": "# Standard library de DragonScript\n\nTECNICA MOVER_N(pasos, direccion) {\n    WHILE pasos > 0 {\n        VOLAR(direccion)\n        pasos = pasos - 1\n    }\n}\n\nTECNICA PONER_N(cantidad, esfera) {\n    WHILE cantidad > 0 {\n        CARGAR(esfera)\n        cantidad = cantidad - 1\n    }\n}\n\nTECNICA DRENAR_N(cantidad, esfera) {\n    WHILE cantidad > 0 {\n        DRENAR(esfera)\n        cantidad = cantidad - 1\n    }\n}\n\nTECNICA IR_AL_ORIGEN(x, y) {\n    # 1. Lleva el cabezal al origen (0,0)\n    WHILE PUEDE_VOLAR(OESTE) {\n        VOLAR(OESTE)\n    }\n    WHILE PUEDE_VOLAR(SUR) {\n        VOLAR(SUR)\n    }\n\n    # 2. Desplaza el cabezal a la celda objetivo (x, y)\n    MOVER_N(x, ESTE)\n    MOVER_N(y, NORTE)\n}",
  "board.py": "\"\"\"\nboard.py\n========\nTablero estilo *Gobstones* para DragonScript, con temática Dragon Ball.\n\nIdea pedagógica\n---------------\nIgual que en Gobstones, hay un **tablero** rectangular de celdas y un\n**cabezal** que se para sobre una celda y se mueve por ella. En DragonScript\nel cabezal es el **GUERRERO** (que *vuela* por el tablero) y, en vez de\n\"bolitas de colores\", las celdas guardan **Esferas del Dragón** de 4 tipos,\nidentificadas por su número de estrellas:\n\n    ESFERA_1  ->  ★         (1 estrella)\n    ESFERA_2  ->  ★★        (2 estrellas)\n    ESFERA_3  ->  ★★★       (3 estrellas)\n    ESFERA_4  ->  ★★★★      (4 estrellas)\n\nEl origen ``(0, 0)`` está en la esquina **inferior izquierda** (como en\nGobstones). VOLAR NORTE sube (aumenta ``y``), VOLAR ESTE va a la derecha\n(aumenta ``x``).\n\nEste módulo NO conoce nada de DragonScript: sólo modela el tablero. El puente\nhacia el lenguaje (funciones VOLAR, CARGAR, etc.) se arma en ``runtime.py``.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom .errors import RuntimeError_, TypeErrorDS\n\n# --- Direcciones ---------------------------------------------------------\nNORTE = \"NORTE\"\nSUR = \"SUR\"\nESTE = \"ESTE\"\nOESTE = \"OESTE\"\nDIRECCIONES = (NORTE, SUR, ESTE, OESTE)\n\n# --- Esferas (los 4 \"colores\") ------------------------------------------\n# Clave interna 1..4 ; nombre expuesto \"ESFERA_n\".\nESFERAS = (1, 2, 3, 4)\nNOMBRE_ESFERA = {\n    1: \"ESFERA_1\",\n    2: \"ESFERA_2\",\n    3: \"ESFERA_3\",\n    4: \"ESFERA_4\",\n}\nESTRELLAS = {1: \"★\", 2: \"★★\", 3: \"★★★\", 4: \"★★★★\"}\n\n# Símbolos cortos para el render compacto de cada celda.\nSIMBOLO = {1: \"1\", 2: \"2\", 3: \"3\", 4: \"4\"}\n\n\ndef esfera_desde_valor(valor):\n    \"\"\"Traduce un valor DragonScript (``\"ESFERA_1\"`` o ``1``) a la clave 1..4.\"\"\"\n    if isinstance(valor, bool):\n        raise TypeErrorDS(\"Eso no es una Esfera del Dragón válida.\")\n    if isinstance(valor, (int, float)) and int(valor) in ESFERAS:\n        return int(valor)\n    if isinstance(valor, str):\n        v = valor.strip().upper()\n        for clave, nombre in NOMBRE_ESFERA.items():\n            if v == nombre or v == str(clave):\n                return clave\n    raise TypeErrorDS(\n        \"Esa no es una Esfera del Dragón válida. Usá ESFERA_1..ESFERA_4.\")\n\n\nclass Board:\n    \"\"\"Un tablero rectangular con un cabezal (el GUERRERO).\"\"\"\n\n    def __init__(self, ancho: int = 4, alto: int = 4):\n        self.reiniciar(ancho, alto)\n\n    # ------------------------------------------------------------------\n    def reiniciar(self, ancho: int = 4, alto: int = 4) -> None:\n        if (isinstance(ancho, bool) or isinstance(alto, bool)\n                or not isinstance(ancho, int) or not isinstance(alto, int)):\n            raise TypeErrorDS(\"El tamaño del tablero debe ser en números enteros.\")\n        if ancho < 1 or alto < 1:\n            raise RuntimeError_(\"El tablero debe tener al menos 1x1 celdas.\")\n        self.ancho = ancho\n        self.alto = alto\n        # celdas[(x, y)] -> dict {esfera: cantidad}\n        self.celdas: dict[tuple[int, int], dict[int, int]] = {\n            (x, y): {1: 0, 2: 0, 3: 0, 4: 0}\n            for x in range(ancho) for y in range(alto)\n        }\n        self.x = 0\n        self.y = 0\n\n    # ------------------------------------------------------ movimiento\n    def _delta(self, direccion: str):\n        d = str(direccion).strip().upper()\n        if d == NORTE:\n            return (0, 1)\n        if d == SUR:\n            return (0, -1)\n        if d == ESTE:\n            return (1, 0)\n        if d == OESTE:\n            return (-1, 0)\n        raise TypeErrorDS(\n            f\"'{direccion}' no es una dirección. Usá NORTE, SUR, ESTE u OESTE.\")\n\n    def puede_volar(self, direccion: str) -> bool:\n        dx, dy = self._delta(direccion)\n        nx, ny = self.x + dx, self.y + dy\n        return 0 <= nx < self.ancho and 0 <= ny < self.alto\n\n    def volar(self, direccion: str) -> None:\n        if not self.puede_volar(direccion):\n            raise RuntimeError_(\n                f\"El GUERRERO se estrelló contra el borde: no puede VOLAR {direccion}.\")\n        dx, dy = self._delta(direccion)\n        self.x += dx\n        self.y += dy\n\n    # -------------------------------------------------------- esferas\n    def _celda(self):\n        return self.celdas[(self.x, self.y)]\n\n    def cargar(self, esfera) -> None:\n        clave = esfera_desde_valor(esfera)\n        self._celda()[clave] += 1\n\n    def drenar(self, esfera) -> None:\n        clave = esfera_desde_valor(esfera)\n        if self._celda()[clave] <= 0:\n            raise RuntimeError_(\n                f\"No hay {NOMBRE_ESFERA[clave]} en esta celda para DRENAR.\")\n        self._celda()[clave] -= 1\n\n    def hay(self, esfera) -> bool:\n        clave = esfera_desde_valor(esfera)\n        return self._celda()[clave] > 0\n\n    def cuantas(self, esfera) -> int:\n        clave = esfera_desde_valor(esfera)\n        return self._celda()[clave]\n\n    def __str__(self) -> str:\n        return f\"GUERRERO (cabezal del tablero) en (x={self.x}, y={self.y})\"\n\n    # --------------------------------------------------------- render\n    # --------------------------------------------------------- render\n    def render(self) -> str:\n        \"\"\"Dibuja el tablero en ASCII dividiendo cada celda en una sub-grilla 2x2 (E1..E4).\"\"\"\n        lineas = []\n        lineas.append(\n            f\"  TABLERO {self.ancho}x{self.alto}   \"\n            f\"Cabezal GUERRERO en (x={self.x}, y={self.y}) 🐉\"\n        )\n        lineas.append(\n            \"  Sub-grilla 2x2 por celda = [E1 E2] / [E3 E4]  (E1=1★ E2=2★ E3=3★\"\n            \" E4=4★)\"\n        )\n        lineas.append(\"\")\n\n        borde_horizontal = \"  +\" + \"-----+ \" * self.ancho\n\n        for y in range(self.alto - 1, -1, -1):  # De arriba hacia abajo\n            lineas.append(borde_horizontal)\n\n            # Línea superior de la celda: E1 (Arriba-Izq) y E2 (Arriba-Der)\n            fila_superior = []\n            # Línea inferior de la celda: E3 (Abajo-Izq) y E4 (Abajo-Der)\n            fila_inferior = []\n\n            for x in range(self.ancho):\n                c = self.celdas[(x, y)]\n                e1 = str(c[1]) if c[1] > 0 else \" \"\n                e2 = str(c[2]) if c[2] > 0 else \" \"\n                e3 = str(c[3]) if c[3] > 0 else \" \"\n                e4 = str(c[4]) if c[4] > 0 else \" \"\n\n                # Indicador de cabezal si el guerrero está en esta celda\n                es_cabezal = x == self.x and y == self.y\n                izq = \">\" if es_cabezal else \" \"\n                der = \"<\" if es_cabezal else \" \"\n\n                fila_superior.append(f\"{izq}{e1} {e2}{der}\")\n                fila_inferior.append(f\"{izq}{e3} {e4}{der}\")\n\n            lineas.append(f\"y{y} | \" + \" | \".join(fila_superior) + \" |\")\n            lineas.append(f\"   | \" + \" | \".join(fila_inferior) + \" |\")\n\n        lineas.append(borde_horizontal)\n\n        # Etiquetas de columnas (Eje X)\n        etiquetas_x = \"   \" + \" \".join(f\"  x{x}  \" for x in range(self.ancho))\n        lineas.append(etiquetas_x)\n\n        return \"\\n\".join(lineas)\n",
  "cli.py": "import sys\nfrom pathlib import Path\n\nfrom dragonscript.errors import DragonScriptError\nfrom dragonscript.interpreter import Interpreter\nfrom dragonscript.lexer import Lexer\nfrom dragonscript.parser import Parser\n\n\ndef main():\n    if len(sys.argv) < 2:\n        print(\"Uso: dragonscript <archivo.ds>\")\n        sys.exit(1)\n\n    filepath = Path(sys.argv[1]).resolve()\n    with open(filepath, \"r\", encoding=\"utf-8\") as f:\n        user_code = f.read()\n\n    # Cargar la biblioteca global (Biblioteca.ds) si existe\n    stdlib_path = Path(__file__).parent / \"Biblioteca.ds\"\n    stdlib_code = \"\"\n    stdlib_lines = 0\n\n    if stdlib_path.exists():\n        with open(stdlib_path, \"r\", encoding=\"utf-8\") as f:\n            stdlib_code = f.read().strip()\n            if stdlib_code:\n                # Contamos cuántas líneas ocupa la librería para ajustar el reporte de errores\n                stdlib_lines = stdlib_code.count(\"\\n\") + 2\n                stdlib_code = f\"{stdlib_code}\\n\\n\"\n\n    code_completo = stdlib_code + user_code\n\n    try:\n        tokens = Lexer(code_completo).tokenize()\n        ast = Parser(tokens).parse()\n\n        interpreter = Interpreter()\n        interpreter.interpret(ast)\n\n    except DragonScriptError as e:\n        # Si el error ocurrió en el código del usuario, ajustamos el número de línea reportado\n        if hasattr(e, \"line\") and e.line and e.line > stdlib_lines:\n            e.line -= stdlib_lines\n        raise e\n\n    # Mantener la ventana de la GUI abierta si fue inicializada\n    from dragonscript.runtime import gui_instance\n\n    if gui_instance[0] is not None:\n        gui_instance[0].mantener_abierto()\n\n\nif __name__ == \"__main__\":\n    main()",
  "environment.py": "\"\"\"\nenvironment.py\n==============\nSistema de entornos (scopes) anidados de DragonScript.\n\nUn :class:`Environment` almacena los enlaces nombre -> valor de un ámbito. Los\námbitos se encadenan mediante ``parent``: el ámbito global no tiene padre y cada\nllamada a una técnica crea un ámbito local cuyo padre es el ámbito donde se\ndefinió la técnica (closures básicos).\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom typing import Any, Optional\n\nfrom .errors import UndefinedVariableError\n\n\nclass Environment:\n    def __init__(self, parent: Optional[\"Environment\"] = None):\n        self.parent = parent\n        self.values: dict[str, Any] = {}\n\n    def define(self, name: str, value: Any) -> None:\n        \"\"\"Define (o redefine) una variable en ESTE ámbito.\"\"\"\n        self.values[name] = value\n\n    def get(self, name: str, line: int | None = None) -> Any:\n        \"\"\"Busca una variable subiendo por la cadena de ámbitos.\"\"\"\n        env: Optional[Environment] = self\n        while env is not None:\n            if name in env.values:\n                return env.values[name]\n            env = env.parent\n        raise UndefinedVariableError(name, line)\n\n    def assign(self, name: str, value: Any, line: int | None = None) -> None:\n        \"\"\"Reasigna una variable existente en la cadena de ámbitos.\"\"\"\n        env: Optional[Environment] = self\n        while env is not None:\n            if name in env.values:\n                env.values[name] = value\n                return\n            env = env.parent\n        raise UndefinedVariableError(name, line)\n\n    def exists(self, name: str) -> bool:\n        env: Optional[Environment] = self\n        while env is not None:\n            if name in env.values:\n                return True\n            env = env.parent\n        return False\n",
  "errors.py": "\"\"\"\nerrors.py\n=========\nExcepciones temáticas de DragonScript.\n\nTodos los errores del lenguaje (léxicos, sintácticos y de ejecución) heredan\nde :class:`DragonScriptError` y muestran mensajes inspirados en Dragon Ball.\n\"\"\"\n\nfrom __future__ import annotations\n\n\nclass DragonScriptError(Exception):\n    \"\"\"Clase base para todos los errores de DragonScript.\"\"\"\n\n    def __init__(self, message: str, line: int | None = None,\n                 column: int | None = None):\n        self.raw_message = message\n        self.line = line\n        self.column = column\n        super().__init__(self._format())\n\n    def _format(self) -> str:\n        if self.line is not None:\n            return f\"{self.message_prefix} {self.raw_message} en línea {self.line}\"\n        return f\"{self.message_prefix} {self.raw_message}\"\n\n    @property\n    def message_prefix(self) -> str:\n        return \"¡Error de DragonScript!\"\n\n\nclass LexerError(DragonScriptError):\n    \"\"\"Error durante la tokenización (el Scouter explota).\"\"\"\n\n    @property\n    def message_prefix(self) -> str:\n        return \"¡El Scouter explotó!\"\n\n\nclass ParserError(DragonScriptError):\n    \"\"\"Error de sintaxis (Ki sintáctico inestable).\"\"\"\n\n    @property\n    def message_prefix(self) -> str:\n        return \"¡Error de Ki Sintáctico!\"\n\n\nclass RuntimeError_(DragonScriptError):\n    \"\"\"Error genérico en tiempo de ejecución.\"\"\"\n\n    @property\n    def message_prefix(self) -> str:\n        return \"¡Error de combate!\"\n\n\nclass UndefinedVariableError(RuntimeError_):\n    \"\"\"Se referencia una variable que no existe.\"\"\"\n\n    def __init__(self, name: str, line: int | None = None):\n        super().__init__(f\"El Scouter no detecta '{name}'! Variable no definida.\",\n                         line)\n\n    @property\n    def message_prefix(self) -> str:\n        return \"¡Alerta!\"\n\n\nclass DivisionByZeroError(RuntimeError_):\n    \"\"\"División entre cero.\"\"\"\n\n    def __init__(self, line: int | None = None):\n        super().__init__(\"Ni Vegeta divide entre cero.\", line)\n\n    @property\n    def message_prefix(self) -> str:\n        return \"¡Imposible!\"\n\n\nclass TypeErrorDS(RuntimeError_):\n    \"\"\"Operación entre tipos incompatibles.\"\"\"\n\n    @property\n    def message_prefix(self) -> str:\n        return \"¡Error de transformación de tipo!\"\n\n\nclass StackOverflowError_(RuntimeError_):\n    \"\"\"Demasiada recursión.\"\"\"\n\n    def __init__(self, line: int | None = None):\n        super().__init__(\"Stack overflow: recursión infinita.\", line)\n\n    @property\n    def message_prefix(self) -> str:\n        return \"¡El poder es demasiado!\"\n\n\nclass ArgumentError(RuntimeError_):\n    \"\"\"Número de argumentos incorrecto en una técnica.\"\"\"\n\n    def __init__(self, detail: str = \"Número de argumentos incorrecto.\",\n                 line: int | None = None):\n        super().__init__(detail, line)\n\n    @property\n    def message_prefix(self) -> str:\n        return \"¡Técnica fallida!\"\n",
  "gui_tablero.py": "import time\nimport tkinter as tk\nfrom tkinter import ttk\n\n\nclass TableroGUI:\n\n  def __init__(self, ancho=3, alto=3, cell_size=90):\n    self.ancho = ancho\n    self.alto = alto\n    self.cell_size = cell_size\n\n    # Estados de control de reproducción\n    self.is_playing = False\n    self.delay = 0.3\n    self.reset_requested = False\n\n    self.root = tk.Tk()\n    self.root.title(\"🐉 DragonScript - Tablero Educativo\")\n\n    # Canvas para la grilla\n    canvas_width = self.ancho * self.cell_size\n    canvas_height = self.alto * self.cell_size\n    self.canvas = tk.Canvas(\n        self.root, width=canvas_width, height=canvas_height, bg=\"#1e1e2e\"\n    )\n    self.canvas.pack(padx=15, pady=10)\n\n    # Panel Inferior de Controles\n    control_frame = ttk.Frame(self.root)\n    control_frame.pack(fill=\"x\", padx=15, pady=10)\n\n    self.btn_play = ttk.Button(\n        control_frame, text=\"▶ Play\", command=self.toggle_play\n    )\n    self.btn_play.pack(side=\"left\", padx=5)\n\n    self.btn_reset = ttk.Button(\n        control_frame, text=\"↺ Reset\", command=self.reset\n    )\n    self.btn_reset.pack(side=\"left\", padx=5)\n\n    ttk.Label(control_frame, text=\"Velocidad:\").pack(side=\"left\", padx=(15, 5))\n    self.speed_slider = ttk.Scale(\n        control_frame,\n        from_=0.05,\n        to=1.0,\n        value=0.3,\n        command=self._update_speed,\n    )\n    self.speed_slider.pack(side=\"left\", fill=\"x\", expand=True, padx=5)\n\n  def toggle_play(self):\n    self.is_playing = not self.is_playing\n    self.btn_play.config(text=\"⏸ Pausa\" if self.is_playing else \"▶ Play\")\n\n  def reset(self):\n    self.reset_requested = True\n    self.is_playing = False\n    self.btn_play.config(text=\"▶ Play\")\n\n  def _update_speed(self, val):\n    # Deslizar a la derecha disminuye el delay (más rápido)\n    self.delay = 1.05 - float(val)\n\n  def _esperar_paso(self):\n    \"\"\"Pausa la ejecución mientras esté en Pausa o aguarda el delay en Play.\"\"\"\n    while not self.is_playing and not self.reset_requested:\n      self.root.update()\n      time.sleep(0.05)\n\n    if self.reset_requested:\n      return\n\n    self.root.update()\n    time.sleep(self.delay)\n\n  def renderizar(self, guerrero_pos, celdas):\n        self.canvas.delete(\"all\")\n\n        # Símbolos de estrellas para cada Esfera del Dragón\n        ESTRELLAS_TXT = {1: \"★\", 2: \"2★\", 3: \"3★\", 4: \"4★\"}\n\n        # Posiciones relativas fijas dentro de la celda (x_offset, y_offset)\n        OFFSETS = {\n            1: (0.30, 0.70),  # Superior Izquierda (1 estrella)\n            2: (0.30, 0.30),  # Superior Derecha (2 estrellas)\n            3: (0.70, 0.30),  # Inferior Izquierda (3 estrellas)\n            4: (0.70, 0.70),  # Inferior Derecha (4 estrellas)\n        }\n\n        for x in range(self.ancho):\n            for y in range(self.alto):\n                canvas_x1 = x * self.cell_size\n                canvas_y1 = (self.alto - 1 - y) * self.cell_size\n                canvas_x2 = canvas_x1 + self.cell_size\n                canvas_y2 = canvas_y1 + self.cell_size\n\n                # Grilla\n                self.canvas.create_rectangle(\n                    canvas_x1,\n                    canvas_y1,\n                    canvas_x2,\n                    canvas_y2,\n                    outline=\"#45475a\",\n                    width=2,\n                    fill=\"#313244\",\n                )\n\n                # Coordenadas\n                self.canvas.create_text(\n                    canvas_x1 + 15,\n                    canvas_y2 - 10,\n                    text=f\"({x},{y})\",\n                    fill=\"#6c7086\",\n                    font=(\"Consolas\", 7),\n                )\n\n                # Esferas del Dragón (Sub-grilla 2x2)\n                esferas = celdas.get((x, y), {})\n                if isinstance(esferas, dict):\n                    radio = self.cell_size * 0.16\n\n                    for esfera_id in range(1, 5):\n                        cant = esferas.get(esfera_id, 0)\n                        if cant > 0:\n                            ox, oy = OFFSETS[esfera_id]\n\n                            # Coordenadas del centro de cada cuadrante\n                            cx = canvas_x1 + (self.cell_size * ox)\n                            cy = canvas_y1 + (self.cell_size * oy)\n\n                            # Dibujar Esfera Naranja estilo Dragon Ball\n                            self.canvas.create_oval(\n                                cx - radio,\n                                cy - radio,\n                                cx + radio,\n                                cy + radio,\n                                fill=\"#fab387\",  # Naranja Esfera\n                                outline=\"#fe640b\",  # Borde Naranja Oscuro\n                                width=1.5,\n                            )\n\n                            # Texto: Muestra la cantidad y las estrellas correspondientes (ej: \"1★ x2\" o \"1★\")\n                            texto_esfera = (\n                                f\"{ESTRELLAS_TXT[esfera_id]}\"\n                                if cant == 1\n                                else f\"{cant}x{ESTRELLAS_TXT[esfera_id]}\"\n                            )\n                            self.canvas.create_text(\n                                cx,\n                                cy,\n                                text=texto_esfera,\n                                fill=\"#d20f39\",  # Rojo Dragón\n                                font=(\"Arial\", 7, \"bold\"),\n                            )\n\n                # GUERRERO\n                if (x, y) == guerrero_pos:\n                    self.canvas.create_rectangle(\n                        canvas_x1 + 4,\n                        canvas_y1 + 4,\n                        canvas_x2 - 4,\n                        canvas_y2 - 4,\n                        outline=\"#a6e3a1\",\n                        width=2,\n                    )\n                    self.canvas.create_text(\n                        (canvas_x1 + canvas_x2) / 2,\n                        canvas_y1 + 12,\n                        text=\"🐉 GUERRERO\",\n                        fill=\"#a6e3a1\",\n                        font=(\"Arial\", 7, \"bold\"),\n                    )\n\n        self._esperar_paso()\n\n  def mantener_abierto(self):\n    self.root.mainloop()",
  "interpreter.py": "\"\"\"\ninterpreter.py\n==============\nIntérprete tree-walking de DragonScript.\n\nRecorre el AST producido por el Parser y lo evalúa usando entornos anidados\n(:mod:`dragonscript.environment`). Soporta expresiones aritméticas y lógicas,\ncontrol de flujo (IF/ELSE, WHILE, GRAVITY), definición y llamada de técnicas\n(funciones) con recursividad y closures básicos, y salida mediante SCOUTER.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport sys\nfrom typing import Any\n\nfrom . import ast_nodes as ast\nfrom .environment import Environment\nfrom .runtime import (Technique, BuiltinFunction, ReturnSignal, ds_repr,\n                      is_truthy, register_builtins, VERSION)\nfrom .objects import (DSClass, DSInstance, BoundMethod, UnboundMethod,\n                      OPERATOR_DUNDERS)\nfrom .errors import (DragonScriptError, RuntimeError_, DivisionByZeroError,\n                     TypeErrorDS, StackOverflowError_, ArgumentError,\n                     UndefinedVariableError)\n\n# Centinela para indicar \"sin sobrecarga de operador aplicable\".\n_NO_OVERLOAD = object()\n\n# Límite de profundidad de recursión de técnicas de DragonScript.\nMAX_CALL_DEPTH = 400\n\n# Cada llamada a técnica consume varias tramas (frames) de Python; elevamos el\n# límite de recursión de Python para que se dispare antes nuestro error\n# temático de \"Stack overflow\" que el RecursionError genérico de Python.\nsys.setrecursionlimit(max(sys.getrecursionlimit(), MAX_CALL_DEPTH * 20))\n\n\nclass Interpreter:\n    def __init__(self, output=None):\n        self.globals = Environment()\n        self.environment = self.globals\n        self._out = output if output is not None else sys.stdout\n        self._call_depth = 0\n        register_builtins(self.globals, self._out)\n\n    # ------------------------------------------------------------------ API\n    def interpret(self, program: ast.Program) -> None:\n        \"\"\"Ejecuta un programa completo.\"\"\"\n        for stmt in program.statements:\n            self._execute(stmt)\n\n    def _emit(self, text: str) -> None:\n        self._out.write(text + \"\\n\")\n\n    # ------------------------------------------------------------- ejecución\n    def _execute(self, node: ast.Node) -> Any:\n        method = getattr(self, \"_exec_\" + type(node).__name__, None)\n        if method is None:\n            raise RuntimeError_(f\"Nodo no soportado: {type(node).__name__}\",\n                                getattr(node, \"line\", None))\n        return method(node)\n\n    def _exec_Block(self, node: ast.Block, env: Environment | None = None) -> None:\n        previous = self.environment\n        self.environment = env if env is not None else Environment(previous)\n        try:\n            for stmt in node.statements:\n                self._execute(stmt)\n        finally:\n            self.environment = previous\n\n    def _exec_KIDeclaration(self, node: ast.KIDeclaration) -> None:\n        value = self._evaluate(node.value) if node.value is not None else None\n        self.environment.define(node.name, value)\n\n    def _exec_Assignment(self, node: ast.Assignment) -> None:\n        value = self._evaluate(node.value)\n        self._assign_to_target(node.target, value, node.line)\n\n    def _exec_CompoundAssignment(self, node: ast.CompoundAssignment) -> None:\n        target = node.target\n        if not isinstance(target, (ast.Identifier, ast.MemberAccess, ast.IndexAccess)):\n            raise RuntimeError_(\"La asignación compuesta requiere una variable \"\n                                \"o propiedad\", node.line)\n        current = self._evaluate(target)\n        rhs = self._evaluate(node.value)\n        op = node.operator[0]  # '+', '-', '*', '/'\n        result = self._apply_binary(op, current, rhs, node.line)\n        self._assign_to_target(target, result, node.line)\n\n    def _assign_to_target(self, target: ast.Node, value: Any, line: int) -> None:\n        \"\"\"Asigna ``value`` al objetivo (variable, propiedad o índice).\"\"\"\n        if isinstance(target, ast.Identifier):\n            self.environment.assign(target.name, value, line)\n        elif isinstance(target, ast.IndexAccess):\n            obj = self._evaluate(target.obj)\n            index = self._evaluate(target.index)\n            self._set_index(obj, index, value, line)\n        elif isinstance(target, ast.MemberAccess):\n            obj = self._evaluate(target.obj)\n            via_self = (isinstance(target.obj, ast.Identifier)\n                        and target.obj.name in (\"SELF\", \"YO\"))\n            self._set_member(obj, target.member, value, line, via_self)\n        else:\n            raise RuntimeError_(\"Objetivo de asignación no soportado\", line)\n\n    def _set_member(self, obj: Any, member: str, value: Any, line: int,\n                    via_self: bool) -> None:\n        if isinstance(obj, DSInstance):\n            if member.startswith(\"_\") and not via_self:\n                raise RuntimeError_(\n                    f\"'{member}' es privado: solo el propio guerrero puede \"\n                    f\"modificarlo (usa SELF).\", line)\n            obj.fields[member] = value\n            return\n        if isinstance(obj, DSClass):\n            obj.class_attributes[member] = value\n            return\n        # Objetos del runtime Dragon Ball (Fase 2) u otros con atributos.\n        if hasattr(obj, member):\n            try:\n                setattr(obj, member, value)\n                return\n            except (AttributeError, TypeError):\n                pass\n        if isinstance(obj, dict):\n            obj[member] = value\n            return\n        raise RuntimeError_(\n            f\"No se puede asignar la propiedad '{member}' en ese valor.\", line)\n\n    def _exec_Scouter(self, node: ast.Scouter) -> None:\n        value = self._evaluate(node.expression)\n        self._emit(self._stringify(value))\n\n    def _stringify(self, value: Any) -> str:\n        \"\"\"Convierte a texto respetando el método mágico ``__str__`` si la\n        instancia lo define.\"\"\"\n        if isinstance(value, DSInstance):\n            method = value.klass.find_method(\"__str__\")\n            if method is not None:\n                result = self._call_technique(method, [], 0, self_obj=value)\n                return self._stringify(result)\n        return ds_repr(value)\n\n    def _exec_IfStatement(self, node: ast.IfStatement) -> None:\n        if is_truthy(self._evaluate(node.condition)):\n            self._exec_Block(node.then_branch)\n            return\n        for cond, block in node.elif_branches:\n            if is_truthy(self._evaluate(cond)):\n                self._exec_Block(block)\n                return\n        if node.else_branch is not None:\n            self._exec_Block(node.else_branch)\n\n    def _exec_WhileStatement(self, node: ast.WhileStatement) -> None:\n        while is_truthy(self._evaluate(node.condition)):\n            self._exec_Block(node.body)\n\n    def _exec_ForEachStatement(self, node: ast.ForEachStatement) -> None:\n        iterable = self._evaluate(node.iterable)\n        if not isinstance(iterable, (list, str)):\n            raise TypeErrorDS(\n                \"RASTREAR solo puede recorrer un grupo (lista) o un texto.\",\n                node.line)\n        for element in iterable:\n            loop_env = Environment(self.environment)\n            loop_env.define(node.var_name, element)\n            self._exec_Block(node.body, env=loop_env)\n\n    def _exec_GravityStatement(self, node: ast.GravityStatement) -> None:\n        count = self._evaluate(node.count)\n        if isinstance(count, bool) or not isinstance(count, (int, float)):\n            raise TypeErrorDS(\"GRAVITY requiere un número de repeticiones.\",\n                              node.line)\n        for _ in range(int(count)):\n            self._exec_Block(node.body)\n\n    def _exec_TechniqueDeclaration(self, node: ast.TechniqueDeclaration) -> None:\n        technique = Technique(node, self.environment)\n        self.environment.define(node.name, technique)\n\n    def _exec_WarriorDeclaration(self, node: ast.WarriorDeclaration) -> None:\n        # Resolver las clases padre (deben existir y ser clases).\n        parents: list[DSClass] = []\n        for parent_name in node.parents:\n            parent = self.environment.get(parent_name, node.line)\n            if not isinstance(parent, DSClass):\n                raise TypeErrorDS(\n                    f\"'{parent_name}' no es un WARRIOR del que se pueda evolucionar.\",\n                    node.line)\n            parents.append(parent)\n\n        # Métodos de instancia y estáticos.\n        methods: dict[str, Technique] = {}\n        static_methods: dict[str, Technique] = {}\n        for m in node.methods:\n            technique = Technique(m, self.environment)\n            if m.is_static:\n                static_methods[m.name] = technique\n            else:\n                methods[m.name] = technique\n\n        # Atributos de clase (compartidos), evaluados en el momento de definir.\n        class_attributes: dict[str, Any] = {}\n        for attr_name, value_node in node.class_attributes:\n            class_attributes[attr_name] = self._evaluate(value_node)\n\n        try:\n            klass = DSClass(node.name, parents, methods, static_methods,\n                            class_attributes)\n        except ValueError as exc:\n            raise TypeErrorDS(str(exc), node.line)\n\n        self.environment.define(node.name, klass)\n\n    def _exec_ReturnStatement(self, node: ast.ReturnStatement) -> None:\n        value = self._evaluate(node.value) if node.value is not None else None\n        raise ReturnSignal(value)\n\n    def _exec_ExpressionStatement(self, node: ast.ExpressionStatement) -> None:\n        self._evaluate(node.expression)\n\n    # ------------------------------------------------------------ evaluación\n    def _evaluate(self, node: ast.Node) -> Any:\n        method = getattr(self, \"_eval_\" + type(node).__name__, None)\n        if method is None:\n            raise RuntimeError_(f\"Expresión no soportada: {type(node).__name__}\",\n                                getattr(node, \"line\", None))\n        return method(node)\n\n    def _eval_NumberLiteral(self, node: ast.NumberLiteral) -> Any:\n        return node.value\n\n    def _eval_StringLiteral(self, node: ast.StringLiteral) -> Any:\n        return node.value\n\n    def _eval_BooleanLiteral(self, node: ast.BooleanLiteral) -> Any:\n        return node.value\n\n    def _eval_NullLiteral(self, node: ast.NullLiteral) -> Any:\n        return None\n\n    def _eval_ArrayLiteral(self, node: ast.ArrayLiteral) -> Any:\n        return [self._evaluate(e) for e in node.elements]\n\n    def _eval_RangeLiteral(self, node: ast.RangeLiteral) -> Any:\n        start = self._evaluate(node.start)\n        end = self._evaluate(node.end)\n        for v in (start, end):\n            if isinstance(v, bool) or not isinstance(v, int):\n                raise TypeErrorDS(\n                    \"Un rango [inicio..fin] requiere números enteros.\", node.line)\n        # Rango inclusivo ascendente. Si inicio > fin, el grupo queda vacío.\n        return list(range(start, end + 1))\n\n    def _eval_Identifier(self, node: ast.Identifier) -> Any:\n        return self.environment.get(node.name, node.line)\n\n    def _eval_UnaryOp(self, node: ast.UnaryOp) -> Any:\n        operand = self._evaluate(node.operand)\n        if node.operator == \"-\":\n            if isinstance(operand, bool) or not isinstance(operand, (int, float)):\n                raise TypeErrorDS(\"No puedes negar algo que no es número.\", node.line)\n            return -operand\n        if node.operator == \"NOT\":\n            return not is_truthy(operand)\n        raise RuntimeError_(f\"Operador unario desconocido: {node.operator}\", node.line)\n\n    def _eval_BinaryOp(self, node: ast.BinaryOp) -> Any:\n        # Operadores lógicos con cortocircuito.\n        if node.operator == \"AND\":\n            left = self._evaluate(node.left)\n            if not is_truthy(left):\n                return left\n            return self._evaluate(node.right)\n        if node.operator == \"OR\":\n            left = self._evaluate(node.left)\n            if is_truthy(left):\n                return left\n            return self._evaluate(node.right)\n\n        left = self._evaluate(node.left)\n        right = self._evaluate(node.right)\n        return self._apply_binary(node.operator, left, right, node.line)\n\n    def _apply_binary(self, op: str, left: Any, right: Any, line: int) -> Any:\n        # Sobrecarga de operadores: si el operando izquierdo es una instancia\n        # y su clase define el método mágico correspondiente, lo usamos.\n        overloaded = self._try_operator_overload(op, left, right, line)\n        if overloaded is not _NO_OVERLOAD:\n            return overloaded\n\n        # Igualdad / desigualdad\n        if op == \"==\":\n            return left == right\n        if op == \"!=\":\n            return left != right\n\n        # Concatenación de grupos (listas) con '+'\n        if op == \"+\" and isinstance(left, list) and isinstance(right, list):\n            return left + right\n\n        # Concatenación de cadenas con '+'\n        if op == \"+\":\n            if isinstance(left, str) or isinstance(right, str):\n                return self._stringify(left) + self._stringify(right) \\\n                    if not (isinstance(left, str) and isinstance(right, str)) \\\n                    else left + right\n            self._check_numbers(left, right, line)\n            return left + right\n\n        # Comparaciones\n        if op in (\"<\", \">\", \"<=\", \">=\"):\n            if isinstance(left, str) and isinstance(right, str):\n                pass  # comparación lexicográfica permitida\n            else:\n                self._check_numbers(left, right, line)\n            if op == \"<\":\n                return left < right\n            if op == \">\":\n                return left > right\n            if op == \"<=\":\n                return left <= right\n            return left >= right\n\n        # Aritmética restante\n        self._check_numbers(left, right, line)\n        if op == \"-\":\n            return left - right\n        if op == \"*\":\n            return left * right\n        if op == \"/\":\n            if right == 0:\n                raise DivisionByZeroError(line)\n            result = left / right\n            # Mantener enteros cuando la división es exacta.\n            if isinstance(left, int) and isinstance(right, int) and result.is_integer():\n                return int(result)\n            return result\n        if op == \"%\":\n            if right == 0:\n                raise DivisionByZeroError(line)\n            return left % right\n\n        raise RuntimeError_(f\"Operador desconocido: {op}\", line)\n\n    def _check_numbers(self, left: Any, right: Any, line: int) -> None:\n        for v in (left, right):\n            if isinstance(v, bool) or not isinstance(v, (int, float)):\n                raise TypeErrorDS(\n                    \"No puedes operar aritméticamente con ese tipo.\", line)\n\n    def _try_operator_overload(self, op: str, left: Any, right: Any, line: int) -> Any:\n        \"\"\"Intenta resolver el operador mediante un método mágico de la clase\n        del operando izquierdo. Devuelve ``_NO_OVERLOAD`` si no aplica.\"\"\"\n        if not isinstance(left, DSInstance):\n            return _NO_OVERLOAD\n        dunder = OPERATOR_DUNDERS.get(op)\n        if dunder is None:\n            return _NO_OVERLOAD\n        method = left.klass.find_method(dunder)\n        if method is None:\n            # Caso especial: si define __eq__ pero no __neq__, derivamos !=.\n            if op == \"!=\":\n                eq = left.klass.find_method(\"__eq__\")\n                if eq is not None:\n                    result = self._call_technique(eq, [right], line, self_obj=left)\n                    return not is_truthy(result)\n            return _NO_OVERLOAD\n        return self._call_technique(method, [right], line, self_obj=left)\n\n    # --------------------------------------------------------- acceso/llamada\n    def _eval_MemberAccess(self, node: ast.MemberAccess) -> Any:\n        obj = self._evaluate(node.obj)\n        member = node.member\n        via_self = (isinstance(node.obj, ast.Identifier)\n                    and node.obj.name in (\"SELF\", \"YO\"))\n\n        # --- Instancias de clases DragonScript ---\n        if isinstance(obj, DSInstance):\n            if member.startswith(\"_\") and not via_self:\n                raise RuntimeError_(\n                    f\"'{member}' es privado: solo el propio guerrero puede \"\n                    f\"acceder a él (usa SELF).\", node.line)\n            # 1) Campo de instancia\n            if member in obj.fields:\n                return obj.fields[member]\n            # 2) Método de instancia -> método ligado (lleva SELF)\n            method = obj.klass.find_method(member)\n            if method is not None:\n                return BoundMethod(obj, method)\n            # 3) Método estático accesible desde la instancia\n            static = obj.klass.find_static(member)\n            if static is not None:\n                return static\n            # 4) Atributo de clase (compartido)\n            found, value = obj.klass.find_class_attr(member)\n            if found:\n                return value\n            raise RuntimeError_(\n                f\"El guerrero '{obj.klass.name}' no tiene la propiedad \"\n                f\"'{member}'.\", node.line)\n\n        # --- Clases (acceso a miembros estáticos / atributos / métodos) ---\n        if isinstance(obj, DSClass):\n            static = obj.find_static(member)\n            if static is not None:\n                return static\n            found, value = obj.find_class_attr(member)\n            if found:\n                return value\n            # Método de instancia accedido vía la clase -> método NO ligado.\n            # Permite llamar al método de un padre pasando SELF explícito,\n            # p. ej. ``Padre.__init__(SELF, ...)``.\n            method = obj.find_method(member)\n            if method is not None:\n                return UnboundMethod(obj, method)\n            raise RuntimeError_(\n                f\"La clase '{obj.name}' no tiene el miembro \"\n                f\"'{member}'.\", node.line)\n\n        # --- Objetos del runtime Dragon Ball (Fase 2) / dicts ---\n        if isinstance(obj, dict) and member in obj:\n            return obj[member]\n        if hasattr(obj, member):\n            return getattr(obj, member)\n        raise RuntimeError_(\n            f\"El objeto no tiene la propiedad '{member}'.\", node.line)\n\n    def _eval_CreateExpression(self, node: ast.CreateExpression) -> Any:\n        klass = self.environment.get(node.class_name, node.line)\n        if not isinstance(klass, DSClass):\n            raise TypeErrorDS(\n                f\"'{node.class_name}' no es un WARRIOR que se pueda crear con \"\n                f\"CREATE.\", node.line)\n        instance = DSInstance(klass)\n        args = [self._evaluate(a) for a in node.arguments]\n\n        init = klass.find_method(\"__init__\")\n        if init is not None:\n            self._call_technique(init, args, node.line, self_obj=instance)\n        elif args:\n            raise ArgumentError(\n                f\"El guerrero '{klass.name}' no define un constructor \"\n                f\"(__init__), pero recibió {len(args)} argumento(s).\", node.line)\n        return instance\n\n    def _eval_IndexAccess(self, node: ast.IndexAccess) -> Any:\n        obj = self._evaluate(node.obj)\n        index = self._evaluate(node.index)\n        if isinstance(obj, (list, str)):\n            if not isinstance(index, int) or isinstance(index, bool):\n                raise TypeErrorDS(\"El índice debe ser un número entero.\", node.line)\n            try:\n                return obj[index]\n            except IndexError:\n                raise RuntimeError_(\"Índice fuera de rango.\", node.line)\n        raise TypeErrorDS(\"Ese valor no se puede indexar.\", node.line)\n\n    def _set_index(self, obj: Any, index: Any, value: Any, line: int) -> None:\n        if isinstance(obj, list) and isinstance(index, int) and not isinstance(index, bool):\n            try:\n                obj[index] = value\n                return\n            except IndexError:\n                raise RuntimeError_(\"Índice fuera de rango.\", line)\n        raise TypeErrorDS(\"No se puede asignar a ese índice.\", line)\n\n    def _eval_TechniqueCall(self, node: ast.TechniqueCall) -> Any:\n        callee = self._evaluate(node.callee)\n        args = [self._evaluate(a) for a in node.arguments]\n\n        if isinstance(callee, BuiltinFunction):\n            return callee.call(args)\n\n        if isinstance(callee, BoundMethod):\n            return self._call_technique(callee.technique, args, node.line,\n                                        self_obj=callee.instance)\n\n        if isinstance(callee, UnboundMethod):\n            # El primer argumento es la instancia (SELF explícito).\n            if not args:\n                raise ArgumentError(\n                    f\"El método '{callee.name}' llamado desde la clase \"\n                    f\"'{callee.klass.name}' necesita recibir SELF como primer \"\n                    f\"argumento.\", node.line)\n            return self._call_technique(callee.technique, args[1:], node.line,\n                                        self_obj=args[0])\n\n        if isinstance(callee, Technique):\n            return self._call_technique(callee, args, node.line)\n\n        raise TypeErrorDS(\"Eso no es una técnica que puedas invocar.\", node.line)\n\n    def _call_technique(self, technique: Technique, args: list[Any], line: int,\n                        self_obj: Any = None) -> Any:\n        if len(args) != technique.arity:\n            # Mensaje adaptado: si es un método, hablamos de un método.\n            etiqueta = \"El método\" if self_obj is not None else \"La técnica\"\n            raise ArgumentError(\n                f\"{etiqueta} '{technique.name}' esperaba {technique.arity} \"\n                f\"argumento(s), recibió {len(args)}.\", line)\n\n        self._call_depth += 1\n        if self._call_depth > MAX_CALL_DEPTH:\n            self._call_depth -= 1\n            raise StackOverflowError_(line)\n\n        env = Environment(technique.closure)\n        # Los métodos de instancia reciben SELF de forma implícita.\n        if self_obj is not None:\n            env.define(\"SELF\", self_obj)\n            env.define(\"YO\", self_obj)  # alias en español de SELF\n        for name, value in zip(technique.declaration.params, args):\n            env.define(name, value)\n\n        previous = self.environment\n        self.environment = env\n        try:\n            for stmt in technique.declaration.body.statements:\n                self._execute(stmt)\n            return None\n        except ReturnSignal as ret:\n            return ret.value\n        finally:\n            self.environment = previous\n            self._call_depth -= 1\n\n\ndef run(program: ast.Program, output=None) -> None:\n    \"\"\"Función de conveniencia: interpreta un programa.\"\"\"\n    Interpreter(output=output).interpret(program)\n",
  "lexer.py": "\"\"\"\nlexer.py\n========\nAnalizador léxico (tokenizador) de DragonScript.\n\nConvierte el código fuente (texto) en una lista de :class:`Token`. Soporta\nnúmeros enteros y flotantes, cadenas UTF-8 (con acentos y signos ¡ ¿),\nidentificadores y palabras clave, operadores aritméticos, de comparación y de\nasignación compuesta, comentarios con ``#`` y saltos de línea como\nseparadores de sentencias.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom .tokens import Token, TokenType, KEYWORDS\nfrom .errors import LexerError\n\n\nclass Lexer:\n    \"\"\"Tokenizador de un solo paso sobre el texto fuente.\"\"\"\n\n    def __init__(self, source: str):\n        self.source = source\n        self.pos = 0\n        self.line = 1\n        self.column = 1\n        self.tokens: list[Token] = []\n\n    # ------------------------------------------------------------------ utils\n    def _peek(self, offset: int = 0) -> str:\n        idx = self.pos + offset\n        if idx < len(self.source):\n            return self.source[idx]\n        return \"\\0\"\n\n    def _advance(self) -> str:\n        ch = self.source[self.pos]\n        self.pos += 1\n        if ch == \"\\n\":\n            self.line += 1\n            self.column = 1\n        else:\n            self.column += 1\n        return ch\n\n    def _at_end(self) -> bool:\n        return self.pos >= len(self.source)\n\n    def _add(self, type_: TokenType, lexeme: str, value=None, col: int | None = None):\n        self.tokens.append(\n            Token(type_, lexeme, value, self.line, col if col is not None else self.column))\n\n    # ------------------------------------------------------------------ main\n    def tokenize(self) -> list[Token]:\n        \"\"\"Devuelve la lista completa de tokens, terminada en EOF.\"\"\"\n        while not self._at_end():\n            self._scan_token()\n        # Aseguramos un NEWLINE final para simplificar el parser, y luego EOF.\n        if self.tokens and self.tokens[-1].type != TokenType.NEWLINE:\n            self._add(TokenType.NEWLINE, \"\\\\n\")\n        self._add(TokenType.EOF, \"\")\n        return self.tokens\n\n    def _scan_token(self) -> None:\n        start_col = self.column\n        ch = self._advance()\n\n        # Espacios en blanco (excepto salto de línea) -> ignorar\n        if ch in \" \\t\\r\":\n            return\n\n        # Salto de línea -> separador de sentencias\n        if ch == \"\\n\":\n            # Evitamos NEWLINE duplicados consecutivos.\n            if self.tokens and self.tokens[-1].type != TokenType.NEWLINE:\n                self._add(TokenType.NEWLINE, \"\\\\n\", col=start_col)\n            return\n\n        # Comentarios con '#'\n        if ch == \"#\":\n            while not self._at_end() and self._peek() != \"\\n\":\n                self._advance()\n            return\n\n        # Cadenas\n        if ch == '\"':\n            self._string(start_col)\n            return\n\n        # Números\n        if ch.isdigit():\n            self._number(ch, start_col)\n            return\n\n        # Identificadores / keywords\n        if ch.isalpha() or ch == \"_\":\n            self._identifier(ch, start_col)\n            return\n\n        # Operadores y delimitadores\n        self._operator(ch, start_col)\n\n    # ------------------------------------------------------------- literales\n    def _string(self, start_col: int) -> None:\n        chars: list[str] = []\n        while not self._at_end() and self._peek() != '\"':\n            c = self._advance()\n            if c == \"\\\\\":  # secuencias de escape sencillas\n                nxt = self._advance()\n                chars.append({\"n\": \"\\n\", \"t\": \"\\t\", '\"': '\"',\n                              \"\\\\\": \"\\\\\"}.get(nxt, nxt))\n            else:\n                chars.append(c)\n        if self._at_end():\n            raise LexerError(\"Cadena sin cerrar (falta comilla doble)\", self.line)\n        self._advance()  # consumir la comilla de cierre\n        self._add(TokenType.STRING, '\"' + \"\".join(chars) + '\"',\n                  value=\"\".join(chars), col=start_col)\n\n    def _number(self, first: str, start_col: int) -> None:\n        num = [first]\n        is_float = False\n        while not self._at_end() and self._peek().isdigit():\n            num.append(self._advance())\n        if self._peek() == \".\" and self._peek(1).isdigit():\n            is_float = True\n            num.append(self._advance())  # el punto\n            while not self._at_end() and self._peek().isdigit():\n                num.append(self._advance())\n        text = \"\".join(num)\n        value = float(text) if is_float else int(text)\n        self._add(TokenType.NUMBER, text, value=value, col=start_col)\n\n    def _identifier(self, first: str, start_col: int) -> None:\n        chars = [first]\n        while not self._at_end() and (self._peek().isalnum() or self._peek() == \"_\"):\n            chars.append(self._advance())\n        text = \"\".join(chars)\n        type_ = KEYWORDS.get(text, TokenType.IDENTIFIER)\n        self._add(type_, text, col=start_col)\n\n    # ----------------------------------------------------------- operadores\n    def _operator(self, ch: str, start_col: int) -> None:\n        def match(expected: str) -> bool:\n            if self._peek() == expected:\n                self._advance()\n                return True\n            return False\n\n        # Punto '.' o rango '..' (para [1..10])\n        if ch == \".\":\n            if match(\".\"):\n                self._add(TokenType.DOTDOT, \"..\", col=start_col)\n            else:\n                self._add(TokenType.DOT, \".\", col=start_col)\n            return\n\n        # Delimitadores y operadores de un solo carácter.\n        simple = {\n            \"(\": TokenType.LPAREN, \")\": TokenType.RPAREN,\n            \"{\": TokenType.LBRACE, \"}\": TokenType.RBRACE,\n            \"[\": TokenType.LBRACKET, \"]\": TokenType.RBRACKET,\n            \",\": TokenType.COMMA,\n            \":\": TokenType.COLON,\n            \"%\": TokenType.PERCENT,\n        }\n        if ch in simple:\n            self._add(simple[ch], ch, col=start_col)\n            return\n\n        if ch == \"+\":\n            self._add(TokenType.PLUS_ASSIGN if match(\"=\") else TokenType.PLUS,\n                      \"+=\" if self.source[self.pos - 1] == \"=\" else \"+\", col=start_col)\n            return\n        if ch == \"-\":\n            if match(\"=\"):\n                self._add(TokenType.MINUS_ASSIGN, \"-=\", col=start_col)\n            elif match(\">\"):\n                self._add(TokenType.ARROW, \"->\", col=start_col)\n            else:\n                self._add(TokenType.MINUS, \"-\", col=start_col)\n            return\n        if ch == \"*\":\n            self._add(TokenType.STAR_ASSIGN if match(\"=\") else TokenType.STAR,\n                      \"*=\" if self.source[self.pos - 1] == \"=\" else \"*\", col=start_col)\n            return\n        if ch == \"/\":\n            self._add(TokenType.SLASH_ASSIGN if match(\"=\") else TokenType.SLASH,\n                      \"/=\" if self.source[self.pos - 1] == \"=\" else \"/\", col=start_col)\n            return\n        if ch == \"=\":\n            self._add(TokenType.EQ if match(\"=\") else TokenType.ASSIGN,\n                      \"==\" if self.source[self.pos - 1] == \"=\" else \"=\", col=start_col)\n            return\n        if ch == \"!\":\n            if match(\"=\"):\n                self._add(TokenType.NEQ, \"!=\", col=start_col)\n                return\n            raise LexerError(f\"Carácter desconocido: '!' en línea {self.line}\",\n                             self.line)\n        if ch == \"<\":\n            self._add(TokenType.LTE if match(\"=\") else TokenType.LT,\n                      \"<=\" if self.source[self.pos - 1] == \"=\" else \"<\", col=start_col)\n            return\n        if ch == \">\":\n            self._add(TokenType.GTE if match(\"=\") else TokenType.GT,\n                      \">=\" if self.source[self.pos - 1] == \"=\" else \">\", col=start_col)\n            return\n\n        raise LexerError(f\"Carácter desconocido: '{ch}' en línea {self.line}\",\n                         self.line)\n\n\ndef tokenize(source: str) -> list[Token]:\n    \"\"\"Función de conveniencia: tokeniza una cadena fuente.\"\"\"\n    return Lexer(source).tokenize()\n",
  "objects.py": "\"\"\"\nobjects.py\n==========\nTipos del runtime para la Programación Orientada a Objetos (POO) de DragonScript.\n\nEn DragonScript, las *clases* se declaran con ``WARRIOR`` (un guerrero es un\nmolde del que salen combatientes concretos) y las *instancias* se crean con\n``CREATE``. La herencia se expresa con ``EVOLVES`` (un guerrero evoluciona a\npartir de otro), soportando herencia múltiple mediante linealización C3\n(el mismo algoritmo de MRO que usa Python).\n\nEste módulo define:\n\n* :class:`DSClass`    — una clase de DragonScript.\n* :class:`DSInstance` — una instancia (objeto) de una clase.\n* :class:`BoundMethod` — un método ligado a una instancia (lleva su ``SELF``).\n* :func:`c3_linearize` — orden de resolución de métodos (MRO) para herencia.\n\nLa convención de encapsulación es sencilla y predecible: los miembros cuyo\nnombre empieza por ``_`` se consideran **privados** y solo pueden accederse\ndesde dentro de la propia clase mediante ``SELF``.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom typing import Any, Optional\n\n\n# Mapa de operador -> nombre del método mágico para sobrecarga de operadores.\nOPERATOR_DUNDERS = {\n    \"+\": \"__add__\",\n    \"-\": \"__sub__\",\n    \"*\": \"__mul__\",\n    \"/\": \"__div__\",\n    \"%\": \"__mod__\",\n    \"==\": \"__eq__\",\n    \"!=\": \"__neq__\",\n    \"<\": \"__lt__\",\n    \">\": \"__gt__\",\n    \"<=\": \"__lte__\",\n    \">=\": \"__gte__\",\n}\n\n\ndef c3_linearize(cls: \"DSClass\") -> list[\"DSClass\"]:\n    \"\"\"Calcula el MRO (Method Resolution Order) mediante linealización C3.\n\n    Es el mismo algoritmo que utiliza Python para resolver la herencia\n    múltiple de forma consistente y determinista.\n    \"\"\"\n\n    def merge(sequences: list[list[\"DSClass\"]]) -> list[\"DSClass\"]:\n        result: list[\"DSClass\"] = []\n        sequences = [list(seq) for seq in sequences if seq]\n        while sequences:\n            head = None\n            for seq in sequences:\n                candidate = seq[0]\n                # Un candidato es válido si no aparece en la \"cola\" de\n                # ninguna otra secuencia.\n                if not any(candidate in s[1:] for s in sequences):\n                    head = candidate\n                    break\n            if head is None:\n                raise ValueError(\n                    \"¡Fusión imposible de linaje! No se puede resolver el \"\n                    \"orden de herencia (MRO inconsistente).\")\n            result.append(head)\n            new_sequences = []\n            for s in sequences:\n                filtered = [c for c in s if c is not head]\n                if filtered:\n                    new_sequences.append(filtered)\n            sequences = new_sequences\n        return result\n\n    parent_linearizations = [c3_linearize(p) for p in cls.parents]\n    return [cls] + merge(parent_linearizations + [list(cls.parents)])\n\n\nclass DSClass:\n    \"\"\"Representa una clase (``WARRIOR``) de DragonScript.\"\"\"\n\n    def __init__(self, name: str, parents: list[\"DSClass\"],\n                 methods: dict, static_methods: dict, class_attributes: dict):\n        self.name = name\n        self.parents = parents\n        self.methods = methods                # nombre -> Technique (instancia)\n        self.static_methods = static_methods  # nombre -> Technique (estático)\n        self.class_attributes = class_attributes  # nombre -> valor (compartido)\n        # Orden de resolución de métodos (incluye a la propia clase).\n        self.mro = c3_linearize(self)\n\n    # --------------------------------------------------------- resolución\n    def find_method(self, name: str) -> Optional[Any]:\n        \"\"\"Busca un método de instancia recorriendo el MRO.\"\"\"\n        for klass in self.mro:\n            if name in klass.methods:\n                return klass.methods[name]\n        return None\n\n    def find_static(self, name: str) -> Optional[Any]:\n        \"\"\"Busca un método estático recorriendo el MRO.\"\"\"\n        for klass in self.mro:\n            if name in klass.static_methods:\n                return klass.static_methods[name]\n        return None\n\n    def find_class_attr(self, name: str):\n        \"\"\"Busca un atributo de clase recorriendo el MRO.\n\n        Devuelve una tupla ``(encontrado, valor)`` para poder distinguir un\n        atributo con valor ``NULL`` de la ausencia del atributo.\n        \"\"\"\n        for klass in self.mro:\n            if name in klass.class_attributes:\n                return True, klass.class_attributes[name]\n        return False, None\n\n    def set_class_attr(self, name: str, value: Any) -> bool:\n        \"\"\"Asigna un atributo de clase ya existente en el MRO. Devuelve\n        ``True`` si se encontró y actualizó.\"\"\"\n        for klass in self.mro:\n            if name in klass.class_attributes:\n                klass.class_attributes[name] = value\n                return True\n        return False\n\n    def __repr__(self) -> str:\n        return f\"<warrior {self.name}>\"\n\n    def __str__(self) -> str:\n        return f\"<warrior {self.name}>\"\n\n\nclass DSInstance:\n    \"\"\"Representa una instancia (objeto) de una clase de DragonScript.\"\"\"\n\n    def __init__(self, klass: DSClass):\n        self.klass = klass\n        self.fields: dict[str, Any] = {}\n\n    def __repr__(self) -> str:\n        return self._default_str()\n\n    def __str__(self) -> str:\n        return self._default_str()\n\n    def _default_str(self) -> str:\n        # Representación por defecto cuando la clase no define __str__.\n        if self.fields:\n            campos = \", \".join(f\"{k}={v}\" for k, v in self.fields.items()\n                               if not k.startswith(\"_\"))\n            return f\"<{self.klass.name} {campos}>\" if campos else f\"<{self.klass.name}>\"\n        return f\"<{self.klass.name}>\"\n\n\nclass BoundMethod:\n    \"\"\"Un método de instancia ligado a su objeto (transporta ``SELF``).\"\"\"\n\n    __slots__ = (\"instance\", \"technique\")\n\n    def __init__(self, instance: DSInstance, technique: Any):\n        self.instance = instance\n        self.technique = technique\n\n    @property\n    def name(self) -> str:\n        return self.technique.name\n\n    def __repr__(self) -> str:\n        return f\"<bound method {self.technique.name} of {self.instance.klass.name}>\"\n\n\nclass UnboundMethod:\n    \"\"\"Un método de instancia accedido a través de la clase (no ligado).\n\n    Permite llamadas explícitas al método de una clase padre pasando la\n    instancia como primer argumento, al estilo ``Padre.__init__(SELF, ...)``.\n    \"\"\"\n\n    __slots__ = (\"klass\", \"technique\")\n\n    def __init__(self, klass: DSClass, technique: Any):\n        self.klass = klass\n        self.technique = technique\n\n    @property\n    def name(self) -> str:\n        return self.technique.name\n\n    def __repr__(self) -> str:\n        return f\"<unbound method {self.technique.name} of {self.klass.name}>\"\n",
  "parser.py": "\"\"\"\nparser.py\n=========\nParser descendente recursivo de DragonScript.\n\nConsume la lista de tokens producida por el :class:`~dragonscript.lexer.Lexer`\ny construye el AST (:mod:`dragonscript.ast_nodes`). Implementa la precedencia\nde operadores tradicional:\n\n    or  <  and  <  igualdad  <  comparación  <  suma  <  producto  <  unario\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom . import ast_nodes as ast\nfrom .errors import ParserError\nfrom .tokens import Token, TokenType\n\n\nclass Parser:\n\n  def __init__(self, tokens: list[Token]):\n    self.tokens = tokens\n    self.pos = 0\n\n  # ------------------------------------------------------------ utilidades\n  def _peek(self, offset: int = 0) -> Token:\n    idx = self.pos + offset\n    if idx < len(self.tokens):\n      return self.tokens[idx]\n    return self.tokens[-1]  # EOF\n\n  def _current(self) -> Token:\n    return self._peek()\n\n  def _advance(self) -> Token:\n    tok = self.tokens[self.pos]\n    if self.pos < len(self.tokens) - 1:\n      self.pos += 1\n    return tok\n\n  def _check(self, type_: TokenType) -> bool:\n    return self._current().type == type_\n\n  def _match(self, *types: TokenType) -> bool:\n    if self._current().type in types:\n      self._advance()\n      return True\n    return False\n\n  def _expect(self, type_: TokenType, message: str) -> Token:\n    if self._check(type_):\n      return self._advance()\n    tok = self._current()\n    raise ParserError(f\"{message} (se encontró '{tok.lexeme}')\", tok.line)\n\n  def _skip_newlines(self) -> None:\n    while self._check(TokenType.NEWLINE):\n      self._advance()\n\n  # ------------------------------------------------------------------ main\n  def parse(self) -> ast.Program:\n    program = ast.Program(line=1)\n    self._skip_newlines()\n    while not self._check(TokenType.EOF):\n      program.statements.append(self._statement())\n      self._skip_newlines()\n    return program\n\n  # ------------------------------------------------------------ sentencias\n  def _statement(self) -> ast.Node:\n    tok = self._current()\n\n    if tok.type == TokenType.KI:\n      return self._ki_declaration()\n    if tok.type == TokenType.ROSHI:\n      return self._roshi_declaration()\n    if tok.type == TokenType.SCOUTER:\n      return self._scouter()\n    if tok.type == TokenType.IF:\n      return self._if_statement()\n    if tok.type == TokenType.WHILE:\n      return self._while_statement()\n    if tok.type == TokenType.FOREACH:\n      return self._foreach_statement()\n    if tok.type == TokenType.GRAVITY:\n      return self._gravity_statement()\n    if tok.type == TokenType.TECHNIQUE:\n      return self._technique_declaration()\n    if tok.type == TokenType.WARRIOR:\n      return self._warrior_declaration()\n    if tok.type == TokenType.RETURN:\n      return self._return_statement()\n\n    # Asignación o expresión suelta.\n    return self._assignment_or_expression()\n\n  def _block(self) -> ast.Block:\n    statements: list[ast.Statement] = []\n\n    # Ignorar saltos de línea opcionales antes de la llave de apertura\n    while self._match(TokenType.NEWLINE):\n      pass\n\n    self._expect(\n        TokenType.LBRACE, \"Se esperaba '{' para iniciar el cuerpo del bloque\"\n    )\n\n    # Ignorar saltos de línea tras abrir la llave\n    while self._match(TokenType.NEWLINE):\n      pass\n\n    while not self._check(TokenType.RBRACE) and not self._check(TokenType.EOF):\n      statements.append(self._statement())\n      while self._match(TokenType.NEWLINE):\n        pass\n\n    self._expect(\n        TokenType.RBRACE, \"Se esperaba '}' para cerrar el cuerpo del bloque\"\n    )\n\n    # Ignorar saltos de línea opcionales tras cerrar la llave\n    while self._match(TokenType.NEWLINE):\n      pass\n\n    return ast.Block(statements=statements)\n\n  def _ki_declaration(self) -> ast.KIDeclaration:\n    line = self._advance().line  # consume KI\n    name = self._expect(\n        TokenType.IDENTIFIER, \"Se esperaba un nombre de variable tras 'KI'\"\n    ).lexeme\n    value = None\n    if self._match(TokenType.ASSIGN):\n      value = self._expression()\n    self._end_statement()\n    return ast.KIDeclaration(name=name, value=value, line=line)\n\n  def _scouter(self) -> ast.Scouter:\n    line = self._advance().line  # consume SCOUTER\n    expr = self._expression()\n    self._end_statement()\n    return ast.Scouter(expression=expr, line=line)\n\n  def _if_statement(self) -> ast.IfStatement:\n    line = self._advance().line  # consume IF\n    condition = self._expression()\n    then_branch = self._block()\n    node = ast.IfStatement(\n        condition=condition, then_branch=then_branch, line=line\n    )\n\n    # Cadena de ELSE / ELSE IF\n    while self._check(TokenType.ELSE):\n      self._advance()  # consume ELSE\n      if self._check(TokenType.IF):\n        self._advance()  # consume IF\n        elif_cond = self._expression()\n        elif_block = self._block()\n        node.elif_branches.append((elif_cond, elif_block))\n      else:\n        node.else_branch = self._block()\n        break\n    return node\n\n  def _while_statement(self) -> ast.WhileStatement:\n    line = self._advance().line  # consume WHILE\n    condition = self._expression()\n    body = self._block()\n    return ast.WhileStatement(condition=condition, body=body, line=line)\n\n  def _foreach_statement(self) -> ast.ForEachStatement:\n    line = self._advance().line  # consume RASTREAR (FOREACH)\n    var_name = self._expect(\n        TokenType.IDENTIFIER,\n        \"Se esperaba un nombre de variable tras 'RASTREAR'\",\n    ).lexeme\n    self._expect(\n        TokenType.IN_, \"Se esperaba 'EN' tras la variable del recorrido\"\n    )\n    iterable = self._expression()\n    body = self._block()\n    return ast.ForEachStatement(\n        var_name=var_name, iterable=iterable, body=body, line=line\n    )\n\n  def _gravity_statement(self) -> ast.GravityStatement:\n    line = self._advance().line  # consume GRAVITY\n    count = self._expression()\n    body = self._block()\n    return ast.GravityStatement(count=count, body=body, line=line)\n\n  def _technique_declaration(self) -> ast.TechniqueDeclaration:\n    line = self._advance().line  # consume TECHNIQUE\n    name = self._expect(\n        TokenType.IDENTIFIER, \"Se esperaba el nombre de la técnica\"\n    ).lexeme\n    self._expect(\n        TokenType.LPAREN, \"Se esperaba '(' tras el nombre de la técnica\"\n    )\n    params: list[str] = []\n    if not self._check(TokenType.RPAREN):\n      params.append(\n          self._expect(\n              TokenType.IDENTIFIER, \"Se esperaba un parámetro\"\n          ).lexeme\n      )\n      while self._match(TokenType.COMMA):\n        params.append(\n            self._expect(\n                TokenType.IDENTIFIER, \"Se esperaba un parámetro\"\n            ).lexeme\n        )\n    self._expect(TokenType.RPAREN, \"Se esperaba ')' tras los parámetros\")\n    self._skip_newlines()  \n    body = self._block()\n    return ast.TechniqueDeclaration(\n        name=name, params=params, body=body, line=line\n    )\n\n  def _roshi_declaration(self) -> ast.TechniqueDeclaration:\n    line = self._advance().line  # consume ROSHI\n    name = self._expect(\n        TokenType.IDENTIFIER, \"Se esperaba el nombre del procedimiento tras 'ROSHI'\"\n    ).lexeme\n    self._expect(\n        TokenType.LPAREN, \"Se esperaba '(' tras el nombre del procedimiento\"\n    )\n    params: list[str] = []\n    if not self._check(TokenType.RPAREN):\n      params.append(\n          self._expect(\n              TokenType.IDENTIFIER, \"Se esperaba un parámetro\"\n          ).lexeme\n      )\n      while self._match(TokenType.COMMA):\n        params.append(\n            self._expect(\n                TokenType.IDENTIFIER, \"Se esperaba un parámetro\"\n            ).lexeme\n        )\n    self._expect(TokenType.RPAREN, \"Se esperaba ')' tras los parámetros\")\n    self._skip_newlines()  \n    body = self._block()\n\n    # Validación para evitar TRANSMITIR/RETURN dentro de un ROSHI:\n    for stmt in body.statements:\n      if isinstance(stmt, ast.ReturnStatement) and stmt.value is not None:\n        raise ParserError(\"¡Un entrenamiento de ROSHI no debe TRANSMITIR ningún valor!\", stmt.line)\n\n    return ast.TechniqueDeclaration(\n        name=name, params=params, body=body, line=line\n    )\n\n  def _warrior_declaration(self) -> ast.WarriorDeclaration:\n    line = self._advance().line  # consume WARRIOR\n    name = self._expect(\n        TokenType.IDENTIFIER, \"Se esperaba el nombre de la clase tras 'WARRIOR'\"\n    ).lexeme\n    parents: list[str] = []\n    if self._match(TokenType.EVOLVES):\n      parents.append(\n          self._expect(\n              TokenType.IDENTIFIER,\n              \"Se esperaba el nombre de la clase padre tras 'EVOLVES'\",\n          ).lexeme\n      )\n      while self._match(TokenType.COMMA):\n        parents.append(\n            self._expect(\n                TokenType.IDENTIFIER,\n                \"Se esperaba un nombre de clase padre tras ','\",\n            ).lexeme\n        )\n\n    self._expect(\n        TokenType.LBRACE, \"Se esperaba '{' para abrir el cuerpo de la clase\"\n    )\n    self._skip_newlines()\n\n    methods: list[ast.TechniqueDeclaration] = []\n    class_attributes: list[tuple[str, ast.Node]] = []\n\n    while not self._check(TokenType.RBRACE) and not self._check(TokenType.EOF):\n      is_static = self._match(TokenType.STATIC)\n\n      if self._check(TokenType.TECHNIQUE):\n        method = self._technique_declaration()\n        method.is_static = is_static\n        methods.append(method)\n      elif self._check(TokenType.IDENTIFIER):\n        # Atributo de clase (compartido): ``nombre = valor``.\n        attr_name = self._advance().lexeme\n        self._expect(\n            TokenType.ASSIGN,\n            \"Se esperaba '=' en la declaración del atributo de clase\",\n        )\n        value = self._expression()\n        self._end_statement()\n        class_attributes.append((attr_name, value))\n      else:\n        tok = self._current()\n        raise ParserError(\n            f\"Elemento no válido dentro de la clase '{name}' \"\n            f\"(se encontró '{tok.lexeme}')\",\n            tok.line,\n        )\n      self._skip_newlines()\n\n    self._expect(\n        TokenType.RBRACE, \"Se esperaba '}' para cerrar el cuerpo de la clase\"\n    )\n    return ast.WarriorDeclaration(\n        name=name,\n        parents=parents,\n        methods=methods,\n        class_attributes=class_attributes,\n        line=line,\n    )\n\n  def _return_statement(self) -> ast.ReturnStatement:\n    line = self._advance().line  # consume RETURN\n    value = None\n    if (\n        not self._check(TokenType.NEWLINE)\n        and not self._check(TokenType.RBRACE)\n        and not self._check(TokenType.EOF)\n    ):\n      value = self._expression()\n    self._end_statement()\n    return ast.ReturnStatement(value=value, line=line)\n\n  def _assignment_or_expression(self) -> ast.Node:\n    line = self._current().line\n    expr = self._expression()\n\n    # Asignación simple\n    if self._check(TokenType.ASSIGN):\n      self._advance()\n      value = self._expression()\n      self._end_statement()\n      self._validate_assign_target(expr)\n      return ast.Assignment(target=expr, value=value, line=line)\n\n    # Asignación compuesta\n    compound = {\n        TokenType.PLUS_ASSIGN: \"+=\",\n        TokenType.MINUS_ASSIGN: \"-=\",\n        TokenType.STAR_ASSIGN: \"*=\",\n        TokenType.SLASH_ASSIGN: \"/=\",\n    }\n    if self._current().type in compound:\n      op = compound[self._current().type]\n      self._advance()\n      value = self._expression()\n      self._end_statement()\n      self._validate_assign_target(expr)\n      return ast.CompoundAssignment(\n          target=expr, operator=op, value=value, line=line\n      )\n\n    # Expresión suelta (por ejemplo, una llamada a técnica).\n    self._end_statement()\n    return ast.ExpressionStatement(expression=expr, line=line)\n\n  def _validate_assign_target(self, target: ast.Node) -> None:\n    if not isinstance(\n        target, (ast.Identifier, ast.MemberAccess, ast.IndexAccess)\n    ):\n      raise ParserError(\n          \"Objetivo de asignación inválido\", getattr(target, \"line\", 0)\n      )\n\n  def _end_statement(self) -> None:\n    \"\"\"Consume el separador de sentencia (NEWLINE o EOF o '}').\"\"\"\n    if self._check(TokenType.NEWLINE):\n      self._advance()\n    elif self._check(TokenType.EOF) or self._check(TokenType.RBRACE):\n      return\n    else:\n      tok = self._current()\n      raise ParserError(\n          f\"Se esperaba un salto de línea al final de la sentencia \"\n          f\"(se encontró '{tok.lexeme}')\",\n          tok.line,\n      )\n\n  # ------------------------------------------------------------ expresiones\n  def _expression(self) -> ast.Node:\n    return self._logic_or()\n\n  def _logic_or(self) -> ast.Node:\n    left = self._logic_and()\n    while self._check(TokenType.OR):\n      line = self._advance().line\n      right = self._logic_and()\n      left = ast.BinaryOp(left=left, operator=\"OR\", right=right, line=line)\n    return left\n\n  def _logic_and(self) -> ast.Node:\n    left = self._equality()\n    while self._check(TokenType.AND):\n      line = self._advance().line\n      right = self._equality()\n      left = ast.BinaryOp(left=left, operator=\"AND\", right=right, line=line)\n    return left\n\n  def _equality(self) -> ast.Node:\n    left = self._comparison()\n    while self._current().type in (TokenType.EQ, TokenType.NEQ):\n      op = \"==\" if self._current().type == TokenType.EQ else \"!=\"\n      line = self._advance().line\n      right = self._comparison()\n      left = ast.BinaryOp(left=left, operator=op, right=right, line=line)\n    return left\n\n  def _comparison(self) -> ast.Node:\n    left = self._term()\n    ops = {\n        TokenType.LT: \"<\",\n        TokenType.GT: \">\",\n        TokenType.LTE: \"<=\",\n        TokenType.GTE: \">=\",\n    }\n    while self._current().type in ops:\n      op = ops[self._current().type]\n      line = self._advance().line\n      right = self._term()\n      left = ast.BinaryOp(left=left, operator=op, right=right, line=line)\n    return left\n\n  def _term(self) -> ast.Node:\n    left = self._factor()\n    ops = {TokenType.PLUS: \"+\", TokenType.MINUS: \"-\"}\n    while self._current().type in ops:\n      op = ops[self._current().type]\n      line = self._advance().line\n      right = self._factor()\n      left = ast.BinaryOp(left=left, operator=op, right=right, line=line)\n    return left\n\n  def _factor(self) -> ast.Node:\n    left = self._unary()\n    ops = {TokenType.STAR: \"*\", TokenType.SLASH: \"/\", TokenType.PERCENT: \"%\"}\n    while self._current().type in ops:\n      op = ops[self._current().type]\n      line = self._advance().line\n      right = self._unary()\n      left = ast.BinaryOp(left=left, operator=op, right=right, line=line)\n    return left\n\n  def _unary(self) -> ast.Node:\n    if self._current().type in (TokenType.MINUS, TokenType.NOT):\n      op = \"-\" if self._current().type == TokenType.MINUS else \"NOT\"\n      line = self._advance().line\n      operand = self._unary()\n      return ast.UnaryOp(operator=op, operand=operand, line=line)\n    return self._postfix()\n\n  def _postfix(self) -> ast.Node:\n    expr = self._primary()\n    while True:\n      if self._check(TokenType.LPAREN):\n        expr = self._finish_call(expr)\n      elif self._check(TokenType.DOT):\n        line = self._advance().line\n        # Tras el punto se admite un identificador o un lexema de\n        # palabra clave (p. ej. GOKU.KI), tratándolo como nombre.\n        tok = self._current()\n        if tok.type == TokenType.IDENTIFIER or tok.lexeme.isidentifier():\n          self._advance()\n          member = tok.lexeme\n        else:\n          raise ParserError(\n              f\"Se esperaba un nombre de propiedad tras '.' \"\n              f\"(se encontró '{tok.lexeme}')\",\n              tok.line,\n          )\n        expr = ast.MemberAccess(obj=expr, member=member, line=line)\n      elif self._check(TokenType.LBRACKET):\n        line = self._advance().line\n        index = self._expression()\n        self._expect(\n            TokenType.RBRACKET, \"Se esperaba ']' tras el índice\"\n        )\n        expr = ast.IndexAccess(obj=expr, index=index, line=line)\n      else:\n        break\n    return expr\n\n  def _finish_call(self, callee: ast.Node) -> ast.TechniqueCall:\n    line = self._advance().line  # consume '('\n    args: list[ast.Node] = []\n    if not self._check(TokenType.RPAREN):\n      args.append(self._expression())\n      while self._match(TokenType.COMMA):\n        args.append(self._expression())\n    self._expect(TokenType.RPAREN, \"Se esperaba ')' tras los argumentos\")\n    return ast.TechniqueCall(callee=callee, arguments=args, line=line)\n\n  def _primary(self) -> ast.Node:\n    tok = self._current()\n\n    if tok.type == TokenType.NUMBER:\n      self._advance()\n      return ast.NumberLiteral(value=tok.value, line=tok.line)\n    if tok.type == TokenType.STRING:\n      self._advance()\n      return ast.StringLiteral(value=tok.value, line=tok.line)\n    if tok.type == TokenType.TRUE:\n      self._advance()\n      return ast.BooleanLiteral(value=True, line=tok.line)\n    if tok.type == TokenType.FALSE:\n      self._advance()\n      return ast.BooleanLiteral(value=False, line=tok.line)\n    if tok.type == TokenType.NULL:\n      self._advance()\n      return ast.NullLiteral(line=tok.line)\n    if tok.type == TokenType.IDENTIFIER:\n      self._advance()\n      return ast.Identifier(name=tok.lexeme, line=tok.line)\n    if tok.type == TokenType.CREATE:\n      return self._create_expression()\n    if tok.type == TokenType.LPAREN:\n      self._advance()\n      expr = self._expression()\n      self._expect(\n          TokenType.RPAREN, \"Se esperaba ')' para cerrar la expresión\"\n      )\n      return expr\n    if tok.type == TokenType.LBRACKET:\n      return self._array_literal()\n\n    raise ParserError(f\"Expresión inesperada: '{tok.lexeme}'\", tok.line)\n\n  def _create_expression(self) -> ast.CreateExpression:\n    line = self._advance().line  # consume CREATE\n    class_name = self._expect(\n        TokenType.IDENTIFIER, \"Se esperaba el nombre de la clase tras 'CREATE'\"\n    ).lexeme\n    self._expect(\n        TokenType.LPAREN, \"Se esperaba '(' tras el nombre de la clase\"\n    )\n    args: list[ast.Node] = []\n    if not self._check(TokenType.RPAREN):\n      args.append(self._expression())\n      while self._match(TokenType.COMMA):\n        args.append(self._expression())\n    self._expect(\n        TokenType.RPAREN, \"Se esperaba ')' tras los argumentos de CREATE\"\n    )\n    return ast.CreateExpression(\n        class_name=class_name, arguments=args, line=line\n    )\n\n  def _array_literal(self) -> ast.Node:\n    line = self._advance().line  # consume '['\n    elements: list[ast.Node] = []\n    self._skip_newlines()\n    if not self._check(TokenType.RBRACKET):\n      first = self._expression()\n      # ¿Es un rango [inicio..fin]?\n      if self._check(TokenType.DOTDOT):\n        self._advance()  # consume '..'\n        end = self._expression()\n        self._skip_newlines()\n        self._expect(\n            TokenType.RBRACKET, \"Se esperaba ']' para cerrar el rango\"\n        )\n        return ast.RangeLiteral(start=first, end=end, line=line)\n      elements.append(first)\n      while self._match(TokenType.COMMA):\n        self._skip_newlines()\n        if self._check(TokenType.RBRACKET):\n          break\n        elements.append(self._expression())\n    self._skip_newlines()\n    self._expect(TokenType.RBRACKET, \"Se esperaba ']' para cerrar el array\")\n    return ast.ArrayLiteral(elements=elements, line=line)\n\n\ndef parse(tokens: list[Token]) -> ast.Program:\n  \"\"\"Función de conveniencia: construye el AST a partir de tokens.\"\"\"\n  return Parser(tokens).parse()",
  "runtime.py": "\"\"\"\nruntime.py\n==========\nRuntime base de DragonScript: tipos internos y funciones built-in.\n\nAquí se definen:\n\n* :class:`Technique` — representación en tiempo de ejecución de una función\n  definida por el usuario (con su cierre / closure).\n* :class:`BuiltinFunction` — envoltorio de funciones nativas de Python\n  expuestas a DragonScript.\n* :func:`ds_repr` — conversión de valores DragonScript a texto para SCOUTER.\n* :func:`register_builtins` — registra las funciones matemáticas y utilidades\n  básicas en el ámbito global.\n\"\"\"\n\n# 1. ESTO TIENE QUE IR OBLIGATORIAMENTE PRIMERO\nfrom __future__ import annotations\n\n# 2. Todos los demás imports van abajo\nimport math\nimport sys\nfrom typing import Any, Callable\n\nfrom . import board as board_mod\nfrom .errors import ArgumentError, TypeErrorDS\ntry:\n    from .gui_tablero import TableroGUI\n    HAS_TKINTER = True\nexcept ModuleNotFoundError:\n    TableroGUI = None\n    HAS_TKINTER = False\n\nVERSION = \"1.0.0\"\n\n# Variable de módulo para almacenar la instancia de la GUI\ngui_instance: list = [None]\n\n\nclass ReturnSignal(Exception):\n    \"\"\"Señal interna usada para propagar el valor de un RETURN.\"\"\"\n\n    def __init__(self, value: Any):\n        self.value = value\n        super().__init__(\"return\")\n\n\nclass Technique:\n    \"\"\"Función definida por el usuario con TECHNIQUE.\"\"\"\n\n    def __init__(self, declaration, closure):\n        self.declaration = declaration\n        self.closure = closure  # Environment donde se definió (closure)\n\n    @property\n    def name(self) -> str:\n        return self.declaration.name\n\n    @property\n    def arity(self) -> int:\n        return len(self.declaration.params)\n\n    def __repr__(self) -> str:\n        return f\"<technique {self.name}({', '.join(self.declaration.params)})>\"\n\n\nclass BuiltinFunction:\n    \"\"\"Función nativa de Python expuesta a DragonScript.\"\"\"\n\n    def __init__(self, name: str, fn: Callable[..., Any], arity: int | None = None):\n        self.name = name\n        self.fn = fn\n        self.arity = arity  # None = número variable de argumentos\n\n    def call(self, args: list[Any]):\n        if self.arity is not None and len(args) != self.arity:\n            raise ArgumentError(\n                f\"La función '{self.name}' esperaba {self.arity} argumento(s), \"\n                f\"recibió {len(args)}.\"\n            )\n        return self.fn(*args)\n\n    def __repr__(self) -> str:\n        return f\"<builtin {self.name}>\"\n\n\ndef ds_repr(value: Any) -> str:\n    \"\"\"Convierte un valor DragonScript a su representación textual.\"\"\"\n    if value is None:\n        return \"NULL\"\n    if value is True:\n        return \"TRUE\"\n    if value is False:\n        return \"FALSE\"\n    if isinstance(value, float):\n        # Mostramos 3.0 como 3 si es entero exacto.\n        if value.is_integer():\n            return str(int(value))\n        return str(value)\n    if isinstance(value, list):\n        return \"[\" + \", \".join(ds_repr(v) for v in value) + \"]\"\n    return str(value)\n\n\ndef is_truthy(value: Any) -> bool:\n    \"\"\"Reglas de veracidad de DragonScript.\"\"\"\n    if value is None or value is False:\n        return False\n    if value == 0:\n        return False\n    if isinstance(value, str) and value == \"\":\n        return False\n    if isinstance(value, list) and len(value) == 0:\n        return False\n    return True\n\n\ndef register_builtins(global_env, output=None) -> None:\n    \"\"\"Registra las funciones built-in en el ámbito global dado.\n\n    ``output`` es el flujo de salida (el mismo que usa SCOUTER) para que\n    MOSTRAR_TABLERO se pueda capturar en los tests.\n    \"\"\"\n    out = output if output is not None else sys.stdout\n\n    def _num(x, fname):\n        if isinstance(x, bool) or not isinstance(x, (int, float)):\n            raise TypeErrorDS(f\"'{fname}' requiere un número.\")\n        return x\n\n    def _lista(x, fname):\n        if not isinstance(x, list):\n            raise TypeErrorDS(f\"'{fname}' requiere un grupo (lista).\")\n        return x\n\n    def _cabeza(lista):\n        _lista(lista, \"CABEZA\")\n        if not lista:\n            raise TypeErrorDS(\"CABEZA no funciona con un grupo vacío.\")\n        return lista[0]\n\n    def _cola(lista):\n        _lista(lista, \"COLA\")\n        if not lista:\n            raise TypeErrorDS(\"COLA no funciona con un grupo vacío.\")\n        return lista[1:]\n\n    def _rango(a, b):\n        for v in (a, b):\n            if isinstance(v, bool) or not isinstance(v, int):\n                raise TypeErrorDS(\"RANGO requiere números enteros.\")\n        return list(range(a, b + 1))\n\n    builtins = {\n        # Matemáticas básicas\n        \"ABS\": BuiltinFunction(\"ABS\", lambda x: abs(_num(x, \"ABS\")), 1),\n        \"SQRT\": BuiltinFunction(\"SQRT\", lambda x: math.sqrt(_num(x, \"SQRT\")), 1),\n        \"POW\": BuiltinFunction(\"POW\", lambda x, y: math.pow(_num(x, \"POW\"), _num(y, \"POW\")), 2),\n        \"MAX\": BuiltinFunction(\"MAX\", lambda *xs: max(xs)),\n        \"MIN\": BuiltinFunction(\"MIN\", lambda *xs: min(xs)),\n        \"ROUND\": BuiltinFunction(\"ROUND\", lambda x: round(_num(x, \"ROUND\")), 1),\n        \"FLOOR\": BuiltinFunction(\"FLOOR\", lambda x: math.floor(_num(x, \"FLOOR\")), 1),\n        \"CEIL\": BuiltinFunction(\"CEIL\", lambda x: math.ceil(_num(x, \"CEIL\")), 1),\n        # Utilidades\n        \"LEN\": BuiltinFunction(\"LEN\", lambda x: len(x), 1),\n        \"STR\": BuiltinFunction(\"STR\", lambda x: ds_repr(x), 1),\n        \"NUM\": BuiltinFunction(\"NUM\", lambda x: float(x) if not isinstance(x, bool) else x, 1),\n        \"INPUT\": BuiltinFunction(\"INPUT\", lambda prompt: input(ds_repr(prompt)), 1),\n        # Manipulación de grupos (listas) — temáticas Dragon Ball\n        \"ABSORBER\": BuiltinFunction(\n            \"ABSORBER\", lambda lista, x: _lista(lista, \"ABSORBER\") + [x], 2\n        ),\n        \"CABEZA\": BuiltinFunction(\"CABEZA\", _cabeza, 1),\n        \"COLA\": BuiltinFunction(\"COLA\", _cola, 1),\n        \"LONGITUD\": BuiltinFunction(\"LONGITUD\", lambda x: len(_lista(x, \"LONGITUD\")), 1),\n        \"ESTA_VACIA\": BuiltinFunction(\n            \"ESTA_VACIA\", lambda x: len(_lista(x, \"ESTA_VACIA\")) == 0, 1\n        ),\n        \"RANGO\": BuiltinFunction(\"RANGO\", _rango, 2),\n    }\n    for name, fn in builtins.items():\n        global_env.define(name, fn)\n\n    # --------------------------------------------------------------\n    # TABLERO estilo Gobstones (temática Dragon Ball)\n    tablero = board_mod.Board()\n\n    # --------------------------------------------------------------\n    # TABLERO estilo Gobstones (temática Dragon Ball)\n    tablero = board_mod.Board()\n\n    async def _actualizar_gui():\n        # 1. Escritorio (Tkinter)\n        if HAS_TKINTER and gui_instance[0] is not None:\n            gui_instance[0].renderizar((tablero.x, tablero.y), tablero.celdas)\n        \n        # 2. Web (vía Pyodide / JS)\n        try:\n            import js\n            import json\n            \n            celdas_json = json.dumps({str(k): v for k, v in tablero.celdas.items()})\n            js.actualizarTableroJS(tablero.ancho, tablero.alto, tablero.x, tablero.y, celdas_json)\n            \n            # Cede el hilo principal al navegador por 300ms para que pinte el DOM\n            await asyncio.sleep(0.3)\n        except Exception:\n            pass\n\n    async def _iniciar(ancho, alto):\n        tablero.reiniciar(ancho, alto)\n        if HAS_TKINTER and TableroGUI is not None:\n            gui_instance[0] = TableroGUI(ancho, alto)\n        await _actualizar_gui()\n        return None\n\n    async def _volar(direccion):\n        tablero.volar(direccion)\n        await _actualizar_gui()\n        return None\n\n    async def _cargar(esfera):\n        tablero.cargar(esfera)\n        await _actualizar_gui()\n        return None\n\n    async def _drenar(esfera):\n        tablero.drenar(esfera)\n        await _actualizar_gui()\n        return None\n\n    async def _mostrar_tablero():\n        out.write(tablero.render() + \"\\n\")\n        await _actualizar_gui()\n        return None\n\n    def _iniciar(ancho, alto):\n        tablero.reiniciar(ancho, alto)\n        if HAS_TKINTER and TableroGUI is not None:\n            gui_instance[0] = TableroGUI(ancho, alto)\n        _actualizar_gui()\n        return None\n\n    def _volar(direccion):\n        tablero.volar(direccion)\n        _actualizar_gui()\n        return None\n\n    def _cargar(esfera):\n        tablero.cargar(esfera)\n        _actualizar_gui()\n        return None\n\n    def _drenar(esfera):\n        tablero.drenar(esfera)\n        _actualizar_gui()\n        return None\n\n    def _mostrar_tablero():\n        out.write(tablero.render() + \"\\n\")\n        _actualizar_gui()\n        return None\n\n    board_builtins = {\n        \"INICIAR_TABLERO\": BuiltinFunction(\"INICIAR_TABLERO\", _iniciar, 2),\n        \"VOLAR\": BuiltinFunction(\"VOLAR\", _volar, 1),\n        \"PUEDE_VOLAR\": BuiltinFunction(\"PUEDE_VOLAR\", tablero.puede_volar, 1),\n        \"CARGAR\": BuiltinFunction(\"CARGAR\", _cargar, 1),\n        \"DRENAR\": BuiltinFunction(\"DRENAR\", _drenar, 1),\n        \"HAY\": BuiltinFunction(\"HAY\", tablero.hay, 1),\n        \"CUANTAS\": BuiltinFunction(\"CUANTAS\", tablero.cuantas, 1),\n        \"POSICION_X\": BuiltinFunction(\"POSICION_X\", lambda: tablero.x, 0),\n        \"POSICION_Y\": BuiltinFunction(\"POSICION_Y\", lambda: tablero.y, 0),\n        \"MOSTRAR_TABLERO\": BuiltinFunction(\"MOSTRAR_TABLERO\", _mostrar_tablero, 0),\n    }\n    for name, fn in board_builtins.items():\n        global_env.define(name, fn)\n\n    # Constantes del tablero (valores globales que se pueden usar sin comillas).\n    global_env.define(\"NORTE\", board_mod.NORTE)\n    global_env.define(\"SUR\", board_mod.SUR)\n    global_env.define(\"ESTE\", board_mod.ESTE)\n    global_env.define(\"OESTE\", board_mod.OESTE)\n    for clave, nombre in board_mod.NOMBRE_ESFERA.items():\n        global_env.define(nombre, nombre)  # ESFERA_1 == \"ESFERA_1\"\n    # El GUERRERO es el cabezal: apunta al tablero mismo.\n    global_env.define(\"GUERRERO\", tablero)",
  "tokens.py": "\"\"\"\ntokens.py\n=========\nDefinición de los tipos de token del lenguaje DragonScript.\n\nCada token producido por el Lexer es una instancia de :class:`Token`, que\nalmacena su tipo (:class:`TokenType`), el lexema original, un valor ya\nconvertido (para números) y la posición (línea y columna) para reportar\nerrores temáticos de Dragon Ball.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom enum import Enum, auto\n\n\nclass TokenType(Enum):\n    \"\"\"Enumeración de todos los tipos de token soportados.\"\"\"\n\n    # --- Palabras clave (keywords) temáticas de Dragon Ball ---\n    KI = auto()          # declaración de variable  -> let / var\n    SCOUTER = auto()     # instrucción de salida     -> print\n    ROSHI = auto()\n    IF = auto()          # condicional (SENSAR)      -> if\n    ELSE = auto()        # alternativa (SINO)        -> else\n    WHILE = auto()       # bucle condicional (MIENTRAS) -> while\n    FOREACH = auto()     # recorrido enumerativo (RASTREAR) -> for-each\n    IN_ = auto()         # pertenencia en recorrido (EN)   -> in\n    GRAVITY = auto()     # bucle \"repetir N\" (GRAVEDAD)    -> repeat N\n    TECHNIQUE = auto()   # definición de función (TECNICA) -> def / function\n    RETURN = auto()      # retorno de función (TRANSMITIR) -> return\n    AND = auto()         # y lógico (FUSION)          -> and\n    OR = auto()          # o lógico (DESEO)           -> or\n    NOT = auto()         # negación lógica (INVERTIR) -> not\n    TRUE = auto()        # literal verdadero (CANON)  -> true\n    FALSE = auto()       # literal falso (RELLENO)    -> false\n    NULL = auto()        # literal nulo (VACIO)       -> null / None\n\n    # --- Palabras clave de POO (Programación Orientada a Objetos) ---\n    # Temática: Corporación Cápsula. Una CAPSULA es el molde/plano (clase) y\n    # ACTIVAR una cápsula produce un objeto concreto (instancia).\n    WARRIOR = auto()     # definición de clase (CAPSULA)   -> class\n    CREATE = auto()      # instanciación (ACTIVAR)         -> new\n    EVOLVES = auto()     # herencia (EVOLUCIONA)           -> extends / inherits\n    STATIC = auto()      # miembro estático/de clase (LEGENDARIO) -> static\n\n    # --- Literales e identificadores ---\n    NUMBER = auto()\n    STRING = auto()\n    IDENTIFIER = auto()\n\n    # --- Operadores aritméticos ---\n    PLUS = auto()        # +\n    MINUS = auto()       # -\n    STAR = auto()        # *\n    SLASH = auto()       # /\n    PERCENT = auto()     # %\n\n    # --- Operadores de comparación ---\n    EQ = auto()          # ==\n    NEQ = auto()         # !=\n    LT = auto()          # <\n    GT = auto()          # >\n    LTE = auto()         # <=\n    GTE = auto()         # >=\n\n    # --- Asignación ---\n    ASSIGN = auto()          # =\n    PLUS_ASSIGN = auto()     # +=\n    MINUS_ASSIGN = auto()    # -=\n    STAR_ASSIGN = auto()     # *=\n    SLASH_ASSIGN = auto()    # /=\n\n    # --- Delimitadores ---\n    LPAREN = auto()      # (\n    RPAREN = auto()      # )\n    LBRACE = auto()      # {\n    RBRACE = auto()      # }\n    LBRACKET = auto()    # [\n    RBRACKET = auto()    # ]\n    COMMA = auto()       # ,\n    DOT = auto()         # .\n    DOTDOT = auto()      # ..  (rangos: [1..10])\n    COLON = auto()       # :\n    ARROW = auto()       # ->\n\n    # --- Especiales ---\n    NEWLINE = auto()     # salto de línea (separador de sentencias)\n    EOF = auto()         # fin de fichero\n\n\n# Mapa de palabras reservadas -> tipo de token.\n#\n# DragonScript usa palabras reservadas TEMÁTICAS DEL UNIVERSO DRAGON BALL, en\n# español. Para no romper programas antiguos, las palabras originales en inglés\n# (IF, WHILE, ...) siguen aceptándose como *alias ocultos* del mismo token.\nKEYWORDS = {\n    # ---- Palabras temáticas oficiales (en español) ----\n    \"KI\": TokenType.KI,                 # declarar variable (energía que guardás)\n    \"SCOUTER\": TokenType.SCOUTER,       # mostrar / medir en pantalla\n    \"ROSHI\": TokenType.ROSHI,\n    \"SENSAR\": TokenType.IF,             # if      -> \"sensar\" el ki (comprobar)\n    \"ESQUIVAR\": TokenType.ELSE,         # else    -> esquivar (si no se cumple)\n    \"ENTRENAR\": TokenType.WHILE,        # while   -> entrenar mientras se cumpla\n    \"RASTREAR\": TokenType.FOREACH,      # foreach -> rastrear cada elemento\n    \"EN\": TokenType.IN_,                # in      -> RASTREAR x EN grupo\n    \"GRAVEDAD\": TokenType.GRAVITY,      # repetir N veces (cámara de gravedad)\n    \"TECNICA\": TokenType.TECHNIQUE,     # función / procedimiento\n    \"TRANSMITIR\": TokenType.RETURN,     # return  -> teletransportar el resultado\n    \"FUSION\": TokenType.AND,            # and     -> las dos se fusionan\n    \"DESEO\": TokenType.OR,              # or      -> alcanza con un deseo\n    \"INVERTIR\": TokenType.NOT,          # not     -> invertir (Time Reversal)\n    \"CANON\": TokenType.TRUE,            # true    -> lo canónico\n    \"RELLENO\": TokenType.FALSE,         # false   -> el relleno (filler)\n    \"VACIO\": TokenType.NULL,            # null    -> la nada (Dead Zone)\n    \"CAPSULA\": TokenType.WARRIOR,       # clase / registro (molde de Corp. Cápsula)\n    \"ACTIVAR\": TokenType.CREATE,        # crear objeto (activar una cápsula)\n    \"EVOLUCIONA\": TokenType.EVOLVES,    # herencia\n    \"LEGENDARIO\": TokenType.STATIC,     # miembro estático / de clase\n\n    # ---- Alias ocultos en inglés (compatibilidad hacia atrás) ----\n    \"IF\": TokenType.IF,\n    \"ELSE\": TokenType.ELSE,\n    \"WHILE\": TokenType.WHILE,\n    \"GRAVITY\": TokenType.GRAVITY,\n    \"TECHNIQUE\": TokenType.TECHNIQUE,\n    \"RETURN\": TokenType.RETURN,\n    \"AND\": TokenType.AND,\n    \"OR\": TokenType.OR,\n    \"NOT\": TokenType.NOT,\n    \"TRUE\": TokenType.TRUE,\n    \"FALSE\": TokenType.FALSE,\n    \"NULL\": TokenType.NULL,\n    \"WARRIOR\": TokenType.WARRIOR,\n    \"CREATE\": TokenType.CREATE,\n    \"INVOCAR\": TokenType.CREATE,        # alias histórico de ACTIVAR\n    \"EVOLVES\": TokenType.EVOLVES,\n    \"STATIC\": TokenType.STATIC,\n    # NOTA: \"GUERRERO\" ya NO es palabra clave de clase. Ahora queda libre para\n    # usarse como el cabezal del TABLERO (se define como valor global en runtime).\n}\n\n\nclass Token:\n    \"\"\"Representa una unidad léxica del código fuente.\"\"\"\n\n    __slots__ = (\"type\", \"lexeme\", \"value\", \"line\", \"column\")\n\n    def __init__(self, type_: TokenType, lexeme: str, value=None,\n                 line: int = 0, column: int = 0):\n        self.type = type_\n        self.lexeme = lexeme\n        self.value = value\n        self.line = line\n        self.column = column\n\n    def __repr__(self) -> str:  # pragma: no cover - utilidad de depuración\n        return (f\"Token({self.type.name}, {self.lexeme!r}, \"\n                f\"value={self.value!r}, line={self.line}, col={self.column})\")\n\n    def __eq__(self, other) -> bool:\n        if not isinstance(other, Token):\n            return NotImplemented\n        return (self.type == other.type\n                and self.lexeme == other.lexeme\n                and self.value == other.value)\n",
  "__init__.py": "\"\"\"\nDragonScript\n============\nUn lenguaje de programación interpretado inspirado en el universo de\nDragon Ball, implementado en Python.\n\nFlujo de ejecución::\n\n    Código DragonScript -> Lexer -> Tokens -> Parser -> AST -> Interpreter\n\nUso rápido::\n\n    from dragonscript import run_source\n    run_source('SCOUTER \"¡Hola, Guerrero!\"')\n\"\"\"\n\nfrom __future__ import annotations\n\nimport io\n\nfrom .lexer import Lexer, tokenize\nfrom .parser import Parser, parse\nfrom .interpreter import Interpreter, run\nfrom .errors import DragonScriptError\nfrom .runtime import VERSION\n\n__version__ = VERSION\n__all__ = [\n    \"Lexer\", \"tokenize\", \"Parser\", \"parse\", \"Interpreter\", \"run\",\n    \"run_source\", \"run_source_capture\", \"DragonScriptError\", \"__version__\",\n]\n\n\ndef run_source(source: str, output=None) -> None:\n    \"\"\"Tokeniza, parsea e interpreta código fuente DragonScript.\"\"\"\n    tokens = tokenize(source)\n    program = parse(tokens)\n    Interpreter(output=output).interpret(program)\n\n\ndef run_source_capture(source: str) -> str:\n    \"\"\"Ejecuta código y devuelve todo lo que SCOUTER imprimió como cadena.\"\"\"\n    buffer = io.StringIO()\n    run_source(source, output=buffer)\n    return buffer.getvalue()\n"
};